 1 │ /** @type {import('next').NextConfig} */
 2 │ const nextConfig = {
 3 │   reactStrictMode: true,
 4 │   images: {
 5 │     remotePatterns: [
 6 │       { protocol: "https", hostname: "github.com" },
 7 │       { protocol: "https", hostname: "avatars.githubusercontent.com" },
 8 │     ],
 9 │   },
10 │   async redirects() {
11 │     return [
12 │       { source: "/writings", destination: "/blog", permanent: true },
13 │       { source: "/writings/:slug", destination: "/blog/:slug", permanent: true },
14 │     ];
15 │   },
16 │ };
17 │ 
18 │ export default nextConfig;

