===== components/hero-chart.tsx =====
  1 │ "use client";
  2 │ 
  3 │ import { motion, useReducedMotion } from "motion/react";
  4 │ import { useId } from "react";
  5 │ import { Area, AreaChart, ResponsiveContainer, XAxis, YAxis } from "recharts";
  6 │ import { formatCompactTokens } from "@/lib/ai-activity";
  7 │ import { cn } from "@/lib/utils";
  8 │ 
  9 │ /**
 10 │  * Fig. 1 — the year so far, as one line.
 11 │  *
 12 │  * The plate carries the record, not an ornament. Everything drawn here is a
 13 │  * measurement: the curve is tokens per day, the labels are the scale it is
 14 │  * read against, and there is nothing else — no gridlines, no frame, no
 15 │  * tooltip. A hero is looked at, not interrogated, so the figure answers the
 16 │  * only question it is asked from across the room: how much, and which way.
 17 │  */
 18 │ 
 19 │ export type HeroChartPoint = { day: number; value: number };
 20 │ export type HeroChartMonth = { day: number; label: string };
 21 │ 
 22 │ type HeroChartProps = {
 23 │   points: HeroChartPoint[];
 24 │   months: HeroChartMonth[];
 25 │   ticks: number[];
 26 │   xDomain: [number, number];
 27 │   yDomain: [number, number];
 28 │   /** Read instead of the drawing, by anyone who is not looking at it. */
 29 │   description: string;
 30 │   className?: string;
 31 │ };
 32 │ 
 33 │ /**
 34 │  * The scale lives inside the plot, at the left, not in a gutter beside it.
 35 │  *
 36 │  * An axis column costs the curve a fourteenth of its width to draw a rule
 37 │  * nobody reads — and worse than the width, it shifts the whole drawing right,
 38 │  * so the year opens a thumb inside the plate with a blank band beside it and
 39 │  * reads as a picture pushed into its own corner. Asked for no width at all the
 40 │  * axis is dropped outright and the scale goes with it, so it keeps its column
 41 │  * and the plot is pulled back over the column by the same amount: the numbers
 42 │  * are laid on the drawing rather than set beside it, and the year opens at the
 43 │  * plate's own left edge. They land on January, which is the quietest fortnight
 44 │  * of the record and the part standing behind the monogram, so the only thing
 45 │  * they cover is the thing already covered.
 46 │  */
 47 │ const Y_GUTTER = 58;
 48 │ /**
 49 │  * Right edge of the number column, measured from the tick.
 50 │  *
 51 │  * Mono digits, so every number ends on this line and the column reads as one
 52 │  * edge rather than as six labels of different lengths. Set flush to the plate
 53 │  * the longest of them — `100M`, six pixels wider than `25M` — hangs a hair off
 54 │  * the left edge and is shaved by the frame; this holds the whole column a
 55 │  * thumb inside it.
 56 │  */
 57 │ const LABEL_RIGHT = 44;
 58 │ /** The stub after each number — enough to point at the level, not a rule. */
 59 │ const TICK_DASH = 7;
 60 │ /**
 61 │  * And the air between the number and its stub.
 62 │  *
 63 │  * Set tight, the two read as one glyph — `150M—` — and the stub stops being a
 64 │  * mark that points at a level and becomes a hyphen. Held apart, the number is
 65 │  * a label and the stub is the thing indicating where that label lands, which
 66 │  * is what each of them is.
 67 │  */
 68 │ const TICK_GAP = 11;
 69 │ /**
 70 │  * Room above the curve, and below the month row.
 71 │  *
 72 │  * The budget between them is what decides whether the figure sits in its plate
 73 │  * or slumps to the floor of it. Weighted to the top, the curve gets a band of
 74 │  * unused sky it never reaches into while the month row is pressed against the
 75 │  * name beneath — the drawing then reads as bottom-heavy even though the peak
 76 │  * is where the peak belongs. Weighted the other way the curve stands taller in
 77 │  * the same plate and the months get a margin to sit in.
 78 │  */
 79 │ const TOP_ROOM = 12;
 80 │ const BOTTOM_ROOM = 30;
 81 │ 
 82 │ const LABEL_SIZE = 10;
 83 │ 
 84 │ type TickProps = {
 85 │   x?: number;
 86 │   y?: number;
 87 │   payload?: { value: number };
 88 │ };
 89 │ 
 90 │ function labelStyle(size: number): React.CSSProperties {
 91 │   return {
 92 │     fontFamily: "var(--font-mono)",
 93 │     fontSize: size,
 94 │     fontVariantNumeric: "tabular-nums",
 95 │     letterSpacing: "0.02em",
 96 │   };
 97 │ }
 98 │ 
 99 │ function YTick({ x = 0, y = 0, payload, size }: TickProps & { size: number }) {
100 │   // The offsets run to the right of the tick rather than to its left. The plot
101 │   // is pulled back over the axis column, so the tick stands off the plate's
102 │   // left edge and everything the reader sees is laid inward from it. The `x`
103 │   // recharts hands down is used rather than a constant: drop it and the axis
104 │   // renders six empty groups.
105 │   return (
106 │     <g
107 │       transform={`translate(${x},${y})`}
108 │       className="fill-muted-foreground/55 stroke-muted-foreground/35"
109 │     >
110 │       <text
111 │         x={LABEL_RIGHT}
112 │         dy="0.32em"
113 │         textAnchor="end"
114 │         style={labelStyle(size)}
115 │         stroke="none"
116 │       >
117 │         {formatCompactTokens(payload?.value ?? 0)}
118 │       </text>
119 │       <line
120 │         x1={LABEL_RIGHT + TICK_GAP}
121 │         x2={LABEL_RIGHT + TICK_GAP + TICK_DASH}
122 │         y1={0}
123 │         y2={0}
124 │         strokeWidth={1}
125 │       />
