155 │ 
156 │ export function HeroChart({
157 │   points,
158 │   months,
159 │   ticks,
160 │   xDomain,
161 │   yDomain,
162 │   description,
163 │   className,
164 │ }: HeroChartProps) {
165 │   const gradientId = useId();
166 │   const reduceMotion = useReducedMotion();
167 │   const monthLabels = new Map(months.map((m) => [m.day, m.label]));
168 │ 
169 │   return (
170 │     <motion.div
171 │       role="img"
172 │       aria-label={description}
173 │       // Held well back from the foreground, and mixed toward the background
174 │       // rather than faded with alpha.
175 │       //
176 │       // The figure is meant to sit at a distance — behind the name, behind the
177 │       // monogram, a thing seen across a room rather than a chart handed to you.
178 │       // That is aerial perspective, and aerial perspective is contrast
179 │       // collapsing toward the colour of the air, not ink going transparent.
180 │       // A `color-mix` in oklab does exactly that and does it correctly in both
181 │       // themes: the line walks toward near-black in dark and toward near-white
182 │       // in light, where a flat `opacity` would only ever thin it. It also keeps
183 │       // the hairline from winning an argument with the name set in 32px
184 │       // directly under it — the hero would then be a chart with a caption
185 │       // rather than a person with a record. The stops below ride the same
186 │       // colour, so the fill follows the line rather than drifting off it.
187 │       className={cn(
188 │         "size-full text-[color-mix(in_oklab,var(--foreground)_52%,var(--background))]",
189 │         // The haze, and the reason the ridge stops reading as a drawn line.
190 │         //
191 │         // `monotone` clamps the derivative at every extremum, so each peak
192 │         // arrives as a cusp — a point rather than a ridge — and a crisp 1px
193 │         // contour reads as a contour. Neither is fixed by colour. The
194 │         // interpolation cannot change: it is what guarantees the curve never
195 │         // invents a peak (§3), so the geometry stays exactly what was measured
196 │         // and only its edge is softened. Half a pixel is enough — the cusps
197 │         // round off, the hairline stops being a hairline, and nothing moves.
198 │         "[&_.recharts-area]:blur-[0.5px]",
199 │         // The labels stand in the same air. A quarter of a pixel is under the
200 │         // threshold where 10px mono goes mushy but over the one where it reads
201 │         // as sitting on the glass in front of the drawing.
202 │         "[&_text]:blur-[0.25px]",
203 │         // The floor. One-point perspective needs a ground plane or the range
204 │         // is a shape on a field rather than a thing at a distance: the wash
205 │         // rises from the plate's bottom edge, thins out well before the ridge
206 │         // meets it, and never resolves into an edge of its own. It is painted
207 │         // on the plate rather than in the chart so the drawing stands on it,
208 │         // and the month row lands inside it — the labels are on the floor,
209 │         // which is the nearest thing in the picture and the only part of it
210 │         // the reader is standing on.
211 │         "bg-[linear-gradient(to_top,color-mix(in_oklab,var(--foreground)_6%,transparent),transparent_28%)]",
212 │         className,
213 │       )}
214 │       // The record accumulates left to right, so it arrives that way. A wipe
215 │       // rather than a fade: a fade says "an image loaded", a wipe says "this
216 │       // was measured, in this order". Recharts' own animation is not used —
217 │       // it replays on every container resize, which would make the figure
218 │       // redraw itself each time the window is dragged.
219 │       initial={reduceMotion ? false : { clipPath: "inset(0 100% 0 0)" }}
220 │       animate={{ clipPath: "inset(0 0% 0 0)" }}
221 │       transition={{ duration: 0.9, ease: [0.22, 1, 0.36, 1] }}
222 │     >
223 │       <ResponsiveContainer
224 │         width="100%"
225 │         height="100%"
226 │         // Reserve the box on the server so the first paint is the figure and
227 │         // not a hole the figure drops into.
228 │         initialDimension={{ width: 766, height: 394 }}
229 │       >
230 │         <AreaChart
231 │           data={points}
232 │           // The axis keeps its width so it still renders — asked for none it is
233 │           // dropped outright and the scale goes with it — and the plot is
234 │           // pulled back over it by the same amount, so the column costs the
235 │           // drawing nothing and the labels end up laid on it rather than
236 │           // beside it.
237 │           margin={{
238 │             top: TOP_ROOM,
239 │             right: 0,
240 │             bottom: BOTTOM_ROOM,
241 │             left: -Y_GUTTER,
242 │           }}
243 │           // The figure is looked at, not used. No hover state, no crosshair,
244 │           // and no cursor change over a drawing that cannot be clicked.
245 │           style={{ pointerEvents: "none" }}
246 │         >
247 │           <defs>
248 │             <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
249 │               {/* Weight under the line, thinning to nothing before the
250 │                   baseline — so the area reads as the curve's own shadow
251 │                   rather than as a filled shape with an edge of its own. Pulled
252 │                   down with the line it hangs from: a shadow that held its
253 │                   weight while the line receded would read as haze in front of
254 │                   the drawing instead of distance behind it.
255 │ 
256 │                   Carrying more of it than a chart's area would, because the
257 │                   range is the mass and not the outline: a distant ridge is a
258 │                   silhouette whose top edge happens to be a line, and the wash
259 │                   thinning toward the floor is the air between it and the
260 │                   reader rather than a shape with a bottom. */}
261 │               <stop offset="0%" stopColor="currentColor" stopOpacity={0.2} />
262 │               <stop offset="55%" stopColor="currentColor" stopOpacity={0.07} />
263 │               <stop offset="100%" stopColor="currentColor" stopOpacity={0} />
264 │             </linearGradient>
265 │           </defs>
266 │ 
267 │           <XAxis
268 │             type="number"
269 │             dataKey="day"
270 │             domain={xDomain}
271 │             ticks={months.map((m) => m.day)}
272 │             interval={0}
273 │             axisLine={false}
274 │             tickLine={false}
275 │             height={20}
276 │             tick={<XTick labels={monthLabels} size={LABEL_SIZE} />}
277 │           />
278 │           <YAxis
279 │             type="number"
280 │             domain={yDomain}
281 │             ticks={ticks}
282 │             interval={0}
283 │             axisLine={false}
284 │             tickLine={false}
285 │             width={Y_GUTTER}
286 │             tick={<YTick size={LABEL_SIZE} />}
287 │           />
288 │ 
289 │           <Area
290 │             type="monotone"
291 │             dataKey="value"
292 │             stroke="currentColor"
293 │             // Under a pixel, so the ridgeline is the top edge of the mass
294 │             // rather than a rule drawn along it. Taken to zero the silhouette
295 │             // loses its crest and the peaks go soft in the wrong way — the
296 │             // range needs an edge, just not a stroke.
297 │             strokeWidth={0.75}
298 │             strokeLinecap="round"
299 │             strokeLinejoin="round"
300 │             fill={`url(#${gradientId})`}
301 │             fillOpacity={1}
302 │             isAnimationActive={false}
303 │             activeDot={false}
304 │             dot={false}
305 │           />
306 │         </AreaChart>
307 │       </ResponsiveContainer>
308 │     </motion.div>
309 │   );
310 │ }

