  1 │ "use client";
  2 │ 
  3 │ import { useEffect, useRef, useState } from "react";
  4 │ import { cn } from "@/lib/utils";
  5 │ 
  6 │ /**
  7 │  * A menu, hand-rolled because the site has no dropdown anywhere else and a
  8 │  * headless menu library weighs more than the two lists that use it.
  9 │  *
 10 │  * What it owes the Visitor is the WAI-ARIA menu button contract and nothing
 11 │  * more: the trigger says it is expanded, the arrows walk the items, Home and
 12 │  * End jump the ends, Escape closes and hands focus back to the button that
 13 │  * opened it, and a click anywhere else dismisses it. Items are found in the
 14 │  * DOM rather than registered through context, which keeps a `MenuItem` an
 15 │  * ordinary button and a `MenuLink` an ordinary anchor.
 16 │  */
 17 │ export function Menu({
 18 │   label,
 19 │   trigger,
 20 │   className,
 21 │   triggerVariant = "default",
 22 │   triggerClassName,
 23 │   children,
 24 │ }: {
 25 │   /** What the trigger is called, for anyone who cannot see its icon. */
 26 │   label: string;
 27 │   trigger: React.ReactNode;
 28 │   className?: string;
 29 │   triggerVariant?: "default" | "compact";
 30 │   triggerClassName?: string;
 31 │   children: React.ReactNode;
 32 │ }) {
 33 │   const [open, setOpen] = useState(false);
 34 │   const root = useRef<HTMLDivElement>(null);
 35 │   const button = useRef<HTMLButtonElement>(null);
 36 │ 
 37 │   const items = () =>
 38 │     Array.from(
 39 │       root.current?.querySelectorAll<HTMLElement>('[role="menuitem"]') ?? [],
 40 │     );
 41 │ 
 42 │   const close = (returnFocus: boolean) => {
 43 │     setOpen(false);
 44 │     if (returnFocus) button.current?.focus();
 45 │   };
 46 │ 
 47 │   useEffect(() => {
 48 │     if (!open) return;
 49 │ 
 50 │     const onPointerDown = (event: PointerEvent) => {
 51 │       if (!root.current?.contains(event.target as Node)) setOpen(false);
 52 │     };
 53 │     // Capture, so a menu that opens over another control closes before that
 54 │     // control decides it was clicked.
 55 │     document.addEventListener("pointerdown", onPointerDown, true);
 56 │     return () =>
 57 │       document.removeEventListener("pointerdown", onPointerDown, true);
 58 │   }, [open]);
 59 │ 
 60 │   const move = (from: HTMLElement | null, delta: number) => {
 61 │     const list = items();
 62 │     if (list.length === 0) return;
 63 │     const index = from ? list.indexOf(from) : -1;
 64 │     const next = (index + delta + list.length) % list.length;
 65 │     list[next]?.focus();
 66 │   };
 67 │ 
 68 │   return (
 69 │     <div
 70 │       ref={root}
 71 │       className={cn("relative", className)}
 72 │       onKeyDown={(event) => {
 73 │         if (event.key === "Escape" && open) {
 74 │           event.preventDefault();
 75 │           close(true);
 76 │           return;
 77 │         }
 78 │         if (!open) return;
 79 │         const target = event.target as HTMLElement;
 80 │         if (event.key === "ArrowDown") {
 81 │           event.preventDefault();
 82 │           move(target.closest('[role="menuitem"]'), 1);
 83 │         } else if (event.key === "ArrowUp") {
 84 │           event.preventDefault();
 85 │           move(target.closest('[role="menuitem"]'), -1);
 86 │         } else if (event.key === "Home") {
 87 │           event.preventDefault();
 88 │           items()[0]?.focus();
 89 │         } else if (event.key === "End") {
 90 │           event.preventDefault();
 91 │           items().at(-1)?.focus();
 92 │         } else if (event.key === "Tab") {
 93 │           // Tab means the Visitor is done here; the menu should not be a place
 94 │           // they have to walk out of item by item.
 95 │           setOpen(false);
 96 │         }
 97 │       }}
 98 │       // A menu that stays open after picking something reads as a failed
 99 │       // click. Every item closes it, so the handler lives on the container.
100 │       onClick={(event) => {
101 │         if ((event.target as HTMLElement).closest('[role="menuitem"]')) {
102 │           setOpen(false);
103 │         }
104 │       }}
105 │     >
106 │       <button
107 │         ref={button}
108 │         type="button"
109 │         aria-label={label}
110 │         title={label}
111 │         aria-haspopup="menu"
112 │         aria-expanded={open}
113 │         onClick={() => setOpen((was) => !was)}
114 │         onKeyDown={(event) => {
115 │           if (event.key === "ArrowDown" && !open) {
116 │             event.preventDefault();
117 │             setOpen(true);
118 │             // The panel is not mounted yet; focus lands after this paint.
119 │             requestAnimationFrame(() => items()[0]?.focus());
120 │           }
121 │         }}
122 │         className={cn(
123 │           triggerVariant === "compact"
124 │             ? "post-action-button"
125 │             : "action-button",
126 │           triggerClassName,
127 │         )}
128 │       >
129 │         {trigger}
130 │       </button>
131 │ 
132 │       {open ? (
133 │         <div
134 │           role="menu"
135 │           aria-label={label}
136 │           className="absolute top-full right-0 z-50 mt-1 min-w-48 rounded-lg border border-line bg-popover p-1 text-popover-foreground shadow-lg"
137 │         >
138 │           {children}
139 │         </div>
140 │       ) : null}
141 │     </div>
142 │   );
143 │ }
144 │ 
145 │ const ITEM =
146 │   "flex w-full cursor-pointer items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:bg-accent focus-visible:text-foreground [&_svg]:size-4 [&_svg]:shrink-0";
147 │ 
148 │ export function MenuItem({
149 │   className,
150 │   ...props
151 │ }: React.ComponentProps<"button">) {
152 │   return (
153 │     <button role="menuitem" type="button" className={cn(ITEM, className)} {...props} />
154 │   );
155 │ }
156 │ 
157 │ export function MenuLink({ className, ...props }: React.ComponentProps<"a">) {
158 │   return (
159 │     <a
160 │       role="menuitem"
161 │       target="_blank"
162 │       rel="noopener noreferrer"
163 │       className={cn(ITEM, className)}
164 │       {...props}
165 │     />
166 │   );
167 │ }
168 │ 
169 │ /** A hairline between two groups of items that mean different things. */
170 │ export function MenuSeparator() {
171 │   return <div role="separator" className="my-1 h-px bg-line" />;
172 │ }

