 1 │ import { getPostBySlug, getPublishedPosts } from "@/lib/blog";
 2 │ import { postMarkdown } from "@/lib/posts";
 3 │ import { site } from "@/lib/site";
 4 │ 
 5 │ /**
 6 │  * The post as its source.
 7 │  *
 8 │  * Two audiences want this and neither wants HTML: a Visitor who would rather
 9 │  * read the markdown, and a model being handed the URL by the "Open in…"
10 │  * actions on the page. The frontmatter is not served — it is bookkeeping for
11 │  * the build — so the title and date are restated as prose the reader can see.
12 │  *
13 │  * The extension is in the path (`/blog/<slug>/raw.md`) because a Next dynamic
14 │  * segment is the whole segment: `[slug].md` is not a route, it is a folder
15 │  * with a dot in its name.
16 │  */
17 │ export const dynamicParams = false;
18 │ 
19 │ export function generateStaticParams() {
20 │   return getPublishedPosts().map((post) => ({ slug: post.slug }));
21 │ }
