 17 │ import { IconTile } from "@/components/icon-tile";
 18 │ import { Tag } from "@/components/tag";
 19 │ import { destinationHost, type Project, type ProjectKind } from "@/lib/projects";
 20 │ 
 21 │ /**
 22 │  * The tile says what the thing is, not who made it — a terminal for a CLI, a
 23 │  * pane for a VM host. `BoxIcon` is the fallback so an un-typed row still fills
 24 │  * its gutter rather than leaving a hole.
 25 │  */
 26 │ const KIND_ICONS: Record<ProjectKind, typeof BoxIcon> = {
 27 │   cli: TerminalIcon,
 28 │   queue: QueueIcon,
 29 │   app: DeviceIcon,
 30 │   server: ServerIcon,
 31 │   editor: DocumentIcon,
 32 │   canvas: GridIcon,
 33 │   chat: ChatIcon,
 34 │   vm: WindowIcon,
 35 │ };
 36 │ 
 37 │ /**
 38 │  * The project's own mark where it has one, the kind glyph where it does not.
 39 │  *
 40 │  * A silhouette is drawn as a mask in the row's own ink, so a project mark and
 41 │  * a kind glyph are the same weight of thing and the gutter stays one column of
 42 │  * one colour. A mark that carries its own colour is drawn as an image, grey
 43 │  * until the row is under the pointer — the reference's treatment, and the
 44 │  * reason is the same: eight logos at full saturation is a sponsor wall.
 45 │  */
 46 │ function ProjectMark({ project }: { project: Project }) {
 47 │   if (project.logo?.mono) {
 48 │     return (
 49 │       <span
 50 │         aria-hidden
 51 │         className="mx-4 size-6 shrink-0 bg-muted-foreground transition-colors duration-150 ease-out select-none group-hover/project:bg-foreground"
 52 │         style={{
 53 │           maskImage: `url(${project.logo.src})`,
 54 │           maskSize: "contain",
 55 │           maskRepeat: "no-repeat",
 56 │           maskPosition: "center",
 57 │         }}
 58 │       />
 59 │     );
 60 │   }
 61 │ 
 62 │   if (project.logo) {
 63 │     return (
 64 │       // A 465-byte SVG at 24px: there is nothing for the image optimizer to
 65 │       // do to it, and routing it through one would cost a request.
 66 │       // eslint-disable-next-line @next/next/no-img-element
 67 │       <img
 68 │         src={project.logo.src}
 69 │         alt=""
 70 │         aria-hidden
 71 │         width={24}
 72 │         height={24}
 73 │         className="mx-4 size-6 shrink-0 grayscale transition-[filter] duration-150 ease-out select-none group-hover/project:grayscale-0"
 74 │       />
 75 │     );
 76 │   }
 77 │ 
 78 │   const KindIcon = KIND_ICONS[project.kind] ?? BoxIcon;
 79 │   return (
 80 │     <IconTile className="mx-4">
 81 │       <KindIcon />
 82 │     </IconTile>
 83 │   );
 84 │ }
 85 │ 
 86 │ /**
 87 │  * A row is a name and two doors. The name opens the record in place; the arrow
 88 │  * leaves for the thing itself. They are separate controls on purpose — a row
 89 │  * that both expands and navigates makes the reader guess which one a click
 90 │  * bought, and one of the two answers is a lost page.
 91 │  *
 92 │  * One hover surface, though. The row lights as a whole, because it is one
 93 │  * thing; a title that lit while the gutter beside it stayed cold read as two
 94 │  * rows stacked. The arrow is the exception: it darkens on its own, so the
 95 │  * reader can see which of the two doors is under the pointer.
 96 │  */
 97 │ export function ProjectRow({
 98 │   project,
 99 │   headingAs = "h3",
100 │ }: {
101 │   project: Project;
102 │   headingAs?: "h2" | "h3";
103 │ }) {
104 │   const Heading = headingAs;
105 │   const [open, setOpen] = useState(false);
106 │   const detailsId = useId();
107 │   const tags = [project.language, project.note, String(project.year)].filter(
108 │     Boolean,
109 │   ) as string[];
110 │ 
111 │   return (
112 │     <li className="border-b border-line last:border-b-0">
113 │       {/* `relative` scopes the stretched trigger to the row: the record below
114 │           is a sibling, so opening one never puts a button over its own text. */}
115 │       <div className="group/project relative flex items-center transition-[background-color] duration-150 ease-out hover:bg-accent-muted has-[button:active]:bg-accent">
116 │         <ProjectMark project={project} />
117 │ 
118 │         <div className="flex min-w-0 flex-1 items-center gap-2 border-l border-dashed border-line py-4 pr-2 pl-4">
119 │           {/* The whole row toggles, via a pseudo-element rather than a wrapper,
120 │               so the heading stays the button's accessible name. */}
121 │           <button
122 │             type="button"
123 │             aria-expanded={open}
124 │             aria-controls={detailsId}
125 │             onClick={() => setOpen((value) => !value)}
126 │             className="min-w-0 flex-1 touch-manipulation text-left before:absolute before:inset-0"
127 │           >
128 │             <Heading className="truncate leading-snug font-medium">
129 │               {project.name}
130 │             </Heading>
131 │           </button>
132 │ 
133 │           {/* `after:-inset-2` is the hit area: 16px of glyph is a target only a
134 │               mouse can hit, and this is a link a thumb has to be able to take
135 │               without opening the record by mistake. */}
136 │           <a
137 │             href={project.live ?? project.url}
138 │             target="_blank"
139 │             rel="noopener noreferrer"
140 │             aria-label={`${project.name} — ${destinationHost(project)}`}
141 │             className="relative flex size-6 shrink-0 touch-manipulation items-center justify-center text-muted-foreground transition-[color] duration-150 ease-out after:absolute after:-inset-2 hover:text-foreground active:text-foreground"
142 │           >
143 │             <ArrowUpRight className="pointer-events-none size-4" />
144 │           </a>
145 │ 
146 │           <ChevronIcon
147 │             data-open={open}
148 │             aria-hidden
149 │             className="size-4 shrink-0 text-muted-foreground transition-[rotate,color] duration-200 ease-out data-[open=true]:rotate-180 data-[open=true]:text-foreground"
150 │           />
151 │         </div>
152 │       </div>
153 │ 
154 │       {/* `0fr → 1fr` rather than a measured pixel height: the record can be one
155 │           line or three, and a height the row had to measure first is a height
156 │           that is wrong for one frame. */}
157 │       <div id={detailsId} data-open={open} className="project-details grid">
158 │         <div className="overflow-hidden">
159 │           <div className="space-y-4 border-t border-line p-4">
160 │             <p className="typeset typeset-description text-muted-foreground">
161 │               {project.description}
162 │             </p>
163 │             {tags.length > 0 ? (
164 │               <ul className="flex flex-wrap gap-1.5">
165 │                 {tags.map((tag) => (
