138 │             target="_blank"
139 │             rel="noopener noreferrer"
140 │             aria-label={`${project.name} — ${destinationHost(project)}`}
141 │             className="relative flex size-6 shrink-0 touch-manipulation items-center justify-center text-muted-foreground transition-[color] duration-150 ease-out after:absolute after:-inset-2 hover:text-foreground active:text-foreground"
142 │           >
