  6 │  * continues past the content column to the edge of the viewport. Everything
  7 │  * on the site is composed from these six parts — there is no other container.
  8 │  */
  9 │ export function Panel({ className, ...props }: React.ComponentProps<"section">) {
 10 │   return (
 11 │     <section
 12 │       data-slot="panel"
 13 │       className={cn(
 14 │         "screen-line-top screen-line-bottom border-x border-line",
 15 │         className,
 16 │       )}
 17 │       {...props}
 18 │     />
 19 │   );
 20 │ }
 21 │ 
 22 │ export function PanelHeader({
 23 │   className,
 24 │   ...props
 25 │ }: React.ComponentProps<"header">) {
 26 │   return (
 27 │     <header
 28 │       data-slot="panel-header"
 29 │       className={cn(
 30 │         "screen-line-bottom px-4 has-data-[slot=panel-description]:*:data-[slot=panel-title]:screen-line-bottom",
 31 │         className,
 32 │       )}
 33 │       {...props}
 34 │     />
 35 │   );
 36 │ }
 37 │ 
 38 │ /**
 39 │  * A panel title is an `h2` because the usual panel is one section of a page
 40 │  * that already has its own `h1`. A page whose whole content *is* one panel —
 41 │  * a post, the blog index, the 404 — passes `as="h1"` so the document keeps a
 42 │  * top-level heading and the panel's own sub-headings still rank below it.
 43 │  */
 44 │ export function PanelTitle({
 45 │   as: Tag = "h2",
 46 │   className,
 47 │   ...props
 48 │ }: React.ComponentProps<"h2"> & { as?: "h1" | "h2" }) {
 49 │   return (
 50 │     <Tag
 51 │       data-slot="panel-title"
 52 │       className={cn(
 53 │         "group/panel-title font-heading text-3xl font-medium tracking-tight text-balance",
 54 │         className,
 55 │       )}
 56 │       {...props}
 57 │     />
 58 │   );
 59 │ }
 60 │ 
 61 │ /** The count or unit that rides above the baseline of a title. */
 62 │ export function PanelTitleSup({
 63 │   className,
 64 │   ...props
 65 │ }: React.ComponentProps<"sup">) {
 66 │   return (
 67 │     <sup
 68 │       className={cn(
 69 │         "top-[-0.75em] ml-1 text-sm font-medium tracking-normal text-muted-foreground",
 70 │         className,
 71 │       )}
 72 │       {...props}
 73 │     />
 74 │   );
 75 │ }
 76 │ 
 77 │ export function PanelDescription({
 78 │   className,
 79 │   ...props
 80 │ }: React.ComponentProps<"div">) {
 81 │   return (
 82 │     <div
 83 │       data-slot="panel-description"
 84 │       className={cn(
 85 │         "py-4 text-base text-balance text-muted-foreground",
 86 │         className,
 87 │       )}
 88 │       {...props}
 89 │     />
 90 │   );
 91 │ }
 92 │ 
 93 │ export function PanelContent({
 94 │   className,
 95 │   ...props
 96 │ }: React.ComponentProps<"div">) {
 97 │   return (
 98 │     <div data-slot="panel-body" className={cn("p-4", className)} {...props} />
 99 │   );
100 │ }

