===== components/post-search.tsx =====
 1 │ "use client";
 2 │ 
 3 │ import { useEffect, useMemo, useState } from "react";
 4 │ import { PostItem } from "@/components/post-item";
 5 │ import { SearchField, SearchStatus } from "@/components/search-field";
 6 │ import { searchPosts, type PostSummary } from "@/lib/posts";
 7 │ 
 8 │ /**
 9 │  * The index, with a filter over it.
10 │  *
11 │  * The query lives in the component for instant filtering and mirrors the URL
12 │  * without a route transition, so a filtered index can be shared or refreshed
13 │  * without turning every keystroke into a server navigation.
14 │  *
15 │  * The list is not virtualised and does not need to be: it is filtering an
16 │  * array that was already sent, in memory, with no request behind it.
17 │  */
18 │ export function PostSearch({
19 │   posts,
20 │   initialQuery = "",
21 │ }: {
22 │   posts: PostSummary[];
23 │   initialQuery?: string;
24 │ }) {
25 │   const [query, setQuery] = useState(initialQuery);
26 │   const shown = useMemo(() => searchPosts(posts, query), [posts, query]);
27 │ 
28 │   useEffect(() => {
29 │     const onPopState = () => {
30 │       setQuery(new URL(window.location.href).searchParams.get("q") ?? "");
31 │     };
32 │     window.addEventListener("popstate", onPopState);
33 │     return () => window.removeEventListener("popstate", onPopState);
34 │   }, []);
35 │ 
36 │   const updateQuery = (value: string) => {
37 │     setQuery(value);
38 │     const url = new URL(window.location.href);
39 │     const normalized = value.trim();
40 │     if (normalized) url.searchParams.set("q", normalized);
41 │     else url.searchParams.delete("q");
42 │     window.history.replaceState(null, "", `${url.pathname}${url.search}${url.hash}`);
43 │   };
44 │ 
45 │   return (
46 │     <>
47 │       <SearchField
48 │         value={query}
49 │         onChange={updateQuery}
50 │         label="Search posts"
51 │         placeholder="Search posts…"
52 │       />
53 │       <SearchStatus count={shown.length} noun="post" />
54 │ 
55 │       {shown.length > 0 ? (
56 │         <ul>
57 │           {shown.map((post) => (
58 │             <PostItem key={post.slug} post={post} headingAs="h2" />
59 │           ))}
60 │         </ul>
61 │       ) : (
62 │         <p className="p-4 font-mono text-sm text-muted-foreground">
63 │           No posts match “{query}”.
64 │         </p>
65 │       )}
66 │     </>
67 │   );
68 │ }
===== components/search-field.tsx =====
 1 │ "use client";
 2 │ 
 3 │ import { CloseIcon, SearchIcon } from "@/components/icons";
 4 │ 
 5 │ /**
 6 │  * The filter above a list. One field, used by the blog index and the projects
 7 │  * index, so the two pages type the same way — the second search box a Visitor
 8 │  * meets should teach them nothing new.
 9 │  *
10 │  * It owns no state: the list it filters does, because the list is the thing
11 │  * that has to re-render. See `PostSearch` and `ProjectSearch`.
12 │  */
13 │ export function SearchField({
14 │   value,
15 │   onChange,
16 │   label,
17 │   placeholder,
18 │ }: {
19 │   value: string;
20 │   onChange: (value: string) => void;
21 │   label: string;
22 │   placeholder: string;
23 │ }) {
24 │   return (
25 │     <div className="screen-line-bottom p-2">
26 │       <div className="relative flex items-center">
27 │         <SearchIcon
28 │           aria-hidden
29 │           className="pointer-events-none absolute left-3 size-4 text-muted-foreground"
30 │         />
31 │         <input
32 │           type="search"
33 │           value={value}
34 │           onChange={(event) => onChange(event.target.value)}
35 │           onKeyDown={(event) => {
36 │             // Escape empties the field before it does anything else — the same
37 │             // key the palette closes with, doing the same job here.
38 │             if (event.key === "Escape" && value) {
39 │               event.preventDefault();
40 │               onChange("");
41 │             }
42 │           }}
43 │           placeholder={placeholder}
44 │           aria-label={label}
45 │           name="q"
46 │           autoComplete="off"
47 │           spellCheck={false}
48 │           /* 16px on a phone: anything smaller and iOS zooms the page on focus,
49 │              which lands the Visitor somewhere they did not ask to be. */
50 │           className="h-9 w-full rounded-lg border border-border bg-transparent pr-9 pl-9 text-base text-foreground placeholder:text-muted-foreground sm:text-sm dark:bg-input/30"
51 │         />
52 │         {value ? (
53 │           <button
54 │             type="button"
55 │             onClick={() => onChange("")}
56 │             aria-label="Clear search"
57 │             className="absolute right-1.5 flex size-6 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:text-foreground"
58 │           >
59 │             <CloseIcon className="size-4" />
60 │           </button>
61 │         ) : null}
62 │       </div>
63 │     </div>
64 │   );
65 │ }
66 │ 
67 │ /**
68 │  * What a filter did, for someone who cannot see the list change shape. The
69 │  * count is the whole message: a screen reader announcing every matching title
70 │  * on every keystroke is worse than silence.
71 │  */
72 │ export function SearchStatus({
73 │   count,
74 │   noun,
75 │ }: {
76 │   count: number;
77 │   noun: string;
78 │ }) {
79 │   return (
80 │     <p role="status" className="sr-only">
81 │       {count === 1 ? `1 ${noun}` : `${count} ${noun}s`}
82 │     </p>
83 │   );
84 │ }
===== lib/search.ts =====
 1 │ /**
 2 │  * One matcher, for every list on the site that has a filter over it.
 3 │  *
 4 │  * Spaces are dropped as well as case folded, so "codingagents" finds "coding
 5 │  * agents" and "pi queue" finds "pi-queue". Someone typing into a filter is not
 6 │  * typing prose; they are typing until the thing they want is the only thing
 7 │  * left, and every character that has to be exact is a way for that to fail.
 8 │  */
 9 │ const normalize = (text: string) =>
10 │   text.toLowerCase().replaceAll(" ", "").replaceAll("-", "");
11 │ 
12 │ /**
13 │  * `terms` returns the fields worth matching for one item. Blanks are allowed
14 │  * — an optional field is simply absent from the haystack rather than a reason
15 │  * for the caller to build the array conditionally.
16 │  */
17 │ export function filterByQuery<T>(
18 │   items: readonly T[],
19 │   query: string,
20 │   terms: (item: T) => readonly (string | number | undefined)[],
21 │ ): T[] {
22 │   const needle = normalize(query.trim());
23 │   if (!needle) return [...items];
24 │ 
25 │   return items.filter((item) =>
26 │     normalize(
27 │       terms(item)
28 │         .filter((term) => term !== undefined)
29 │         .join(" "),
30 │     ).includes(needle),
31 │   );
32 │ }
