  1 │ "use client";
  2 │ 
  3 │ import Link from "next/link";
  4 │ import { useRouter } from "next/navigation";
  5 │ import { useEffect, useState, useSyncExternalStore } from "react";
  6 │ import {
  7 │   ArrowLeft,
  8 │   ArrowRight,
  9 │   ChatIcon,
 10 │   CheckIcon,
 11 │   ChevronIcon,
 12 │   CopyIcon,
 13 │   DocumentIcon,
 14 │   LinkedinIcon,
 15 │   LinkIcon,
 16 │   ShareIcon,
 17 │   XIcon,
 18 │ } from "@/components/icons";
 19 │ import { Menu, MenuItem, MenuLink, MenuSeparator } from "@/components/menu";
 20 │ 
 21 │ export type PostNeighbour = { slug: string; title: string } | null;
 22 │ 
 23 │ /** Long enough to read, short enough that the button is a button again soon. */
 24 │ const RESET_AFTER = 1600;
 25 │ 
 26 │ function useTransient(): [boolean, () => void] {
 27 │   const [on, setOn] = useState(false);
 28 │   useEffect(() => {
 29 │     if (!on) return;
 30 │     const timer = window.setTimeout(() => setOn(false), RESET_AFTER);
 31 │     return () => window.clearTimeout(timer);
 32 │   }, [on]);
 33 │   return [on, () => setOn(true)];
 34 │ }
 35 │ 
 36 │ async function copy(text: string): Promise<boolean> {
 37 │   try {
 38 │     await navigator.clipboard.writeText(text);
 39 │     return true;
 40 │   } catch {
 41 │     // Denied permission, or an insecure origin. The caller says nothing rather
 42 │     // than claiming a success that did not happen.
 43 │     return false;
 44 │   }
 45 │ }
 46 │ 
 47 │ /**
 48 │  * Everything you can do to a post that is not reading it: take it with you,
 49 │  * pass it on, or move to the one either side.
 50 │  *
 51 │  * They live in one row above the title because they are about the document
 52 │  * rather than in it — putting them after the body would mean scrolling a
 53 │  * thousand words to share something you decided to share in the first
 54 │  * paragraph.
 55 │  */
 56 │ export function PostActions({
 57 │   markdown,
 58 │   rawUrl,
 59 │   url,
 60 │   title,
 61 │   newer,
 62 │   older,
 63 │ }: {
 64 │   /** The post as source, already assembled — see `postMarkdown`. */
 65 │   markdown: string;
 66 │   /** Absolute, because it is handed to a model that has to go and fetch it. */
 67 │   rawUrl: string;
 68 │   url: string;
 69 │   title: string;
 70 │   newer: PostNeighbour;
 71 │   older: PostNeighbour;
 72 │ }) {
 73 │   const router = useRouter();
 74 │   const [copiedPage, markCopiedPage] = useTransient();
 75 │   const [copiedLink, markCopiedLink] = useTransient();
 76 │   // The server has no navigator, and a desktop browser has no share sheet, so
 77 │   // the item is drawn only where it leads somewhere. Read through
 78 │   // `useSyncExternalStore` rather than an effect: the value never changes, it
 79 │   // is simply unknown until hydration, which is exactly what a server snapshot
 80 │   // of `false` says.
 81 │   const canShare = useSyncExternalStore(
 82 │     () => () => {},
 83 │     () => "share" in navigator,
 84 │     () => false,
 85 │   );
 86 │ 
 87 │   useEffect(() => {
 88 │     const onKeyDown = (event: KeyboardEvent) => {
 89 │       // A menu, a search field or the palette already claimed this key.
 90 │       if (event.defaultPrevented) return;
 91 │       if (event.metaKey || event.ctrlKey || event.altKey || event.shiftKey) {
 92 │         return;
 93 │       }
 94 │       const target = event.target as HTMLElement | null;
 95 │       if (
 96 │         target?.isContentEditable ||
 97 │         ["INPUT", "TEXTAREA", "SELECT"].includes(target?.tagName ?? "")
 98 │       ) {
 99 │         return;
100 │       }
101 │ 
102 │       const to =
103 │         event.key === "ArrowLeft"
104 │           ? newer
105 │           : event.key === "ArrowRight"
106 │             ? older
107 │             : null;
108 │       if (!to) return;
109 │       event.preventDefault();
110 │       router.push(`/blog/${to.slug}`);
111 │     };
112 │ 
113 │     window.addEventListener("keydown", onKeyDown);
114 │     return () => window.removeEventListener("keydown", onKeyDown);
115 │   }, [newer, older, router]);
116 │ 
117 │   const prompt = `Read ${rawUrl}, I want to ask questions about it.`;
118 │ 
119 │   return (
120 │     <div className="flex items-center gap-1">
121 │       <div className="inline-flex shrink-0 overflow-visible rounded-lg bg-accent-muted ring-1 ring-inset ring-line/70">
122 │         <button
123 │           type="button"
124 │           onClick={async () => {
125 │             if (await copy(markdown)) markCopiedPage();
126 │           }}
127 │           title="Copy this post as Markdown"
128 │           className="post-action-button rounded-none px-2 text-[0.8125rem] leading-[1.5] font-medium"
129 │         >
130 │           {copiedPage ? <CheckIcon /> : <CopyIcon />}
131 │           <span className="max-sm:sr-only">
132 │             {copiedPage ? "Copied" : "Copy page"}
133 │           </span>
134 │         </button>
135 │ 
136 │         <Menu
137 │           label="More copy options"
138 │           trigger={<ChevronIcon />}
139 │           triggerVariant="compact"
140 │           className="border-l border-line/70"
141 │           triggerClassName="rounded-none px-1.5"
142 │         >
143 │           <MenuLink href={rawUrl}>
144 │             <DocumentIcon />
145 │             View as Markdown
146 │           </MenuLink>
147 │           <MenuSeparator />
148 │           <MenuLink
149 │             href={`https://chatgpt.com/?hint=search&q=${encodeURIComponent(prompt)}`}
150 │           >
151 │             <ChatIcon />
152 │             Open in ChatGPT
153 │           </MenuLink>
154 │           <MenuLink href={`https://claude.ai/new?q=${encodeURIComponent(prompt)}`}>
155 │             <ChatIcon />
156 │             Open in Claude
157 │           </MenuLink>
158 │         </Menu>
159 │       </div>
160 │ 
161 │       <Menu
162 │         label="Share this post"
163 │         trigger={<ShareIcon />}
164 │         triggerVariant="compact"
165 │         triggerClassName="rounded-lg px-1.5"
166 │       >
167 │         <MenuItem
168 │           onClick={async () => {
169 │             if (await copy(url)) markCopiedLink();
170 │           }}
171 │         >
172 │           {copiedLink ? <CheckIcon /> : <LinkIcon />}
173 │           {copiedLink ? "Link copied" : "Copy link"}
174 │         </MenuItem>
175 │         {canShare ? (
176 │           <MenuItem
177 │             onClick={() => {
178 │               // A cancelled share sheet rejects; that is the Visitor changing
179 │               // their mind, not a failure to report.
180 │               void navigator.share({ title, url }).catch(() => {});
181 │             }}
182 │           >
183 │             <ShareIcon />
184 │             Share via…
185 │           </MenuItem>
186 │         ) : null}
187 │         <MenuSeparator />
188 │         <MenuLink
189 │           href={`https://x.com/intent/tweet?url=${encodeURIComponent(url)}&text=${encodeURIComponent(title)}`}
190 │         >
191 │           <XIcon />
192 │           Share on X
193 │         </MenuLink>
194 │         <MenuLink
195 │           href={`https://www.linkedin.com/sharing/share-offsite?url=${encodeURIComponent(url)}`}
196 │         >
197 │           <LinkedinIcon />
198 │           Share on LinkedIn
199 │         </MenuLink>
200 │       </Menu>
201 │ 
202 │       <Neighbour post={newer} direction="newer" />
203 │       <Neighbour post={older} direction="older" />
204 │     </div>
205 │   );
206 │ }
207 │ 
208 │ /**
209 │  * The arrows are named for where they land, not for their position in the
210 │  * feed: "previous" in a list that runs newest-first is a coin toss, and the
211 │  * label is the only thing telling the Visitor which way time runs.
212 │  *
213 │  * Missing neighbours stay out of the toolbar. A dead arrow is visual noise,
214 │  * especially on a one-post blog, and a live arrow keeps its meaning obvious.
215 │  */
216 │ function Neighbour({
217 │   post,
218 │   direction,
219 │ }: {
220 │   post: PostNeighbour;
221 │   direction: "newer" | "older";
222 │ }) {
223 │   const Icon = direction === "newer" ? ArrowLeft : ArrowRight;
224 │   const label =
225 │     direction === "newer" ? "Newer post (←)" : "Older post (→)";
226 │ 
227 │   if (!post) return null;
228 │ 
229 │   return (
230 │     <Link
231 │       href={`/blog/${post.slug}`}
232 │       aria-label={`${label}: ${post.title}`}
233 │       title={`${label} — ${post.title}`}
234 │       className="post-action-button rounded-lg px-1.5"
235 │     >
236 │       <Icon />
237 │     </Link>
238 │   );
239 │ }
===== components/post-neighbours.tsx =====
 1 │ import Link from "next/link";
 2 │ import { ArrowLeft, ArrowRight } from "@/components/icons";
 3 │ import type { PostNeighbour } from "@/components/post-actions";
 4 │ import { cn } from "@/lib/utils";
 5 │ 
 6 │ /**
 7 │  * The two posts either side, at the end of the one you just read — where the
 8 │  * question "what else is there" actually gets asked. The toolbar arrows make
 9 │  * the same jump, but they are icons: this is the place the titles get said.
10 │  *
11 │  * An end of the archive draws an empty half rather than a wide tile, so the
12 │  * older post stays on the side the arrow points at whether or not it has a
13 │  * neighbour to share the row with.
14 │  */
15 │ export function PostNeighbours({
16 │   newer,
17 │   older,
18 │ }: {
19 │   newer: PostNeighbour;
20 │   older: PostNeighbour;
21 │ }) {
22 │   if (!newer && !older) return null;
23 │ 
24 │   return (
25 │     <nav
26 │       aria-label="More posts"
27 │       className="screen-line-bottom grid divide-y divide-line border-x border-line sm:grid-cols-2 sm:divide-x sm:divide-y-0"
28 │     >
29 │       {newer ? <Tile post={newer} direction="newer" /> : <span />}
30 │       {older ? <Tile post={older} direction="older" /> : null}
31 │     </nav>
32 │   );
33 │ }
34 │ 
35 │ function Tile({
36 │   post,
37 │   direction,
38 │ }: {
39 │   post: NonNullable<PostNeighbour>;
40 │   direction: "newer" | "older";
41 │ }) {
42 │   const newer = direction === "newer";
43 │ 
44 │   return (
45 │     <Link
46 │       href={`/blog/${post.slug}`}
47 │       className={cn(
48 │         "flex flex-col gap-1 p-4 transition-colors hover:bg-accent/50",
49 │         !newer && "sm:items-end sm:text-right",
50 │       )}
51 │     >
52 │       <span className="flex items-center gap-1.5 font-mono text-xs tracking-wider text-muted-foreground uppercase">
53 │         {newer ? <ArrowLeft className="size-3.5" /> : null}
54 │         {newer ? "Newer" : "Older"}
55 │         {newer ? null : <ArrowRight className="size-3.5" />}
56 │       </span>
57 │       <span className="font-medium text-balance text-foreground">
58 │         {post.title}
59 │       </span>
60 │     </Link>
61 │   );
62 │ }

