/* Written out rather than run as `fade-in … reverse`: reversing an animation
   that has already finished does not restart it, it re-reads the same finished
   playhead against the other end of the timeline — so the element snaps to the
   far keyframe instead of travelling to it. An exit needs its own name. */
@keyframes fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

/* ---------------------------------------------------------------------------
   The measured cell. A square block on a 2px gutter, no corner rounding, with
   intensity carried by the neutral foreground at five opacities — it was the
   unit the year grid was built from, and Figure 404 is what still draws it.
--------------------------------------------------------------------------- */

.activity-cell {
  background: color-mix(
    in oklab,
    var(--muted-foreground) var(--level, 10%),
    transparent
  );
  position: relative;
  /* Sized by whatever grid places it — Figure 404's columns are fractions of
     the frame, so the cell holds no measurement of its own. */
  animation: fade-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
}

/* An empty frame rather than a fill: the unlit cells of the numeral. */
.activity-cell[data-recorded="false"] {
  background: transparent;
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--muted-foreground) 16%, transparent);
}

/* ---------------------------------------------------------------------------
   A single sweep of light across a line of text, once, on load. The gradient
   is painted into the glyphs themselves and slid from right to left, so the
   highlight travels the line rather than the line changing colour. Spread is
   in `ch` so it scales with the type, and the background is twice the element
   plus two spreads wide so the sweep starts and ends fully off the text.
--------------------------------------------------------------------------- */
@keyframes shimmer-sweep {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: 0 0;
  }
}

.shimmer {
  --shimmer-spread: calc(3ch + 40px);
  --shimmer-angle: 20deg;
   full width of the frame at every viewport.
--------------------------------------------------------------------------- */
.glyph-grid {
  display: grid;
  grid-template-columns: repeat(var(--cols), minmax(0, 1fr));
  gap: 2px;
  width: 100%;
}

.glyph-grid > * {
  aspect-ratio: 1;
}

/* ---------------------------------------------------------------------------
   Prose (MDX) — long-form runs on the serif; structure stays sans.
--------------------------------------------------------------------------- */

.prose {
  /* Set to the frame rather than to a nominal step: the rail is 734px of text
     and the serif ran ~86 characters across it at 17px, well past the line a
     reader can return from without losing their place. 19px brings it back to
     ~75, which is why the body of a post is the largest type on the site. */
  --typeset-size: 1.1875rem;
  --typeset-leading: 1.7;
  --typeset-flow: 1.15em;
  font-family: var(--font-serif);
  color: var(--foreground);
}
.prose h2,
.prose h3 {
  font-family: var(--font-heading);
  font-weight: 500;
  letter-spacing: -0.01em;
  scroll-margin-top: calc(var(--header-height) + 1rem);
}
.prose h2 {
  font-size: 1.5rem;
  line-height: 1.3;
  margin-top: 2.5em;
}
.prose h3 {
  font-size: 1.25rem;
  line-height: 1.35;
  margin-top: 2em;
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 0.75em;
}
.prose > :first-child {
  margin-top: 0;
  visibility: hidden;
  transition:
    grid-template-rows 240ms var(--ease-out-quint),
    visibility 240ms;
}

.project-details[data-open="true"] {
  grid-template-rows: 1fr;
