 1 │ import { GlossaryMark } from "@/components/glossary-mark";
 2 │ import { CustomLink } from "@/components/mdx";
 3 │ import type { GlossaryTerm } from "@/lib/glossary";
 4 │ 
 5 │ /**
 6 │  * The MDX overrides that turn a post's glossary marks into what they mean.
 7 │  *
 8 │  * A mark is written as an ordinary link — `[ⓘ](#figure-out-ability)` — so the
 9 │  * source file stays a markdown file that reads correctly anywhere else, and
10 │  * `raw.md` still hands a model a document with the definitions at the end.
11 │  * Only the rendered page swaps the link for the definition itself.
12 │  */
13 │ export function glossaryComponents(terms: GlossaryTerm[]) {
14 │   const bySlug = new Map(terms.map((entry) => [entry.slug, entry]));
15 │ 
16 │   function GlossaryAnchor(
17 │     props: React.AnchorHTMLAttributes<HTMLAnchorElement>,
18 │   ) {
19 │     const entry = props.href?.startsWith("#")
20 │       ? bySlug.get(props.href.slice(1))
21 │       : undefined;
22 │ 
23 │     if (!entry) return <CustomLink {...props} />;
24 │ 
25 │     return <GlossaryMark term={entry.term} definition={entry.definition} />;
26 │   }
27 │ 
28 │   return { a: GlossaryAnchor };
29 │ }

