30 │ }
31 │ 
32 │ /** The same, as something an `<img>` can take — satori accepts no other form. */
33 │ export function markDataUri(color: string): string {
34 │   return `data:image/svg+xml;utf8,${encodeURIComponent(markSvg(color))}`;
35 │ }
===== lib/slug.ts
 1 │ /**
 2 │  * The id a heading gets, and the anchor a glossary mark points at.
 3 │  *
 4 │  * One function, imported by both the MDX renderer and the glossary split, so
 5 │  * the two cannot drift — a mark that resolves to nothing is a definition the
 6 │  * author wrote and the page silently dropped.
 7 │  */
 8 │ export function slugify(str: unknown): string {
 9 │   return String(str)
10 │     .toLowerCase()
11 │     .trim()
12 │     .replace(/\s+/g, "-")
13 │     .replace(/&/g, "-and-")
14 │     .replace(/[^\w-]+/g, "")
15 │     .replace(/--+/g, "-");
16 │ }
===== lib/utils.ts
1 │ export function cn(...classes: Array<string | undefined | false | null>) {
2 │   return classes.filter(Boolean).join(" ");
3 │ }
===== lib/search.ts
 1 │ /**
 2 │  * One matcher, for every list on the site that has a filter over it.
 3 │  *
 4 │  * Spaces are dropped as well as case folded, so "codingagents" finds "coding
 5 │  * agents" and "pi queue" finds "pi-queue". Someone typing into a filter is not
 6 │  * typing prose; they are typing until the thing they want is the only thing
 7 │  * left, and every character that has to be exact is a way for that to fail.
 8 │  */
 9 │ const normalize = (text: string) =>
10 │   text.toLowerCase().replaceAll(" ", "").replaceAll("-", "");
11 │ 
12 │ /**
13 │  * `terms` returns the fields worth matching for one item. Blanks are allowed
14 │  * — an optional field is simply absent from the haystack rather than a reason
15 │  * for the caller to build the array conditionally.
16 │  */
17 │ export function filterByQuery<T>(
18 │   items: readonly T[],
19 │   query: string,
20 │   terms: (item: T) => readonly (string | number | undefined)[],
21 │ ): T[] {
22 │   const needle = normalize(query.trim());
23 │   if (!needle) return [...items];
24 │ 
25 │   return items.filter((item) =>
26 │     normalize(
27 │       terms(item)
28 │         .filter((term) => term !== undefined)
29 │         .join(" "),
30 │     ).includes(needle),
31 │   );
32 │ }

