17 │ function authorize(req: Request): boolean {
18 │   const expected = process.env.AI_ACTIVITY_INGEST_SECRET;
19 │   if (!expected) return false;
20 │   const header = req.headers.get("authorization");
21 │   if (!header?.startsWith("Bearer ")) return false;
22 │   return secretsEqual(header.slice("Bearer ".length), expected);
23 │ }
24 │ 
25 │ export async function POST(req: Request) {
26 │   if (!authorize(req)) {
27 │     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
28 │   }
29 │ 
30 │   let body: unknown;
31 │   try {
32 │     body = await req.json();
