38 │   if (!payload || !payloadDaysWithinHistory(payload)) {
39 │     return NextResponse.json({ error: "Invalid payload" }, { status: 400 });
40 │   }
41 │ 
42 │   try {
43 │     const { url } = await publishAiActivityPayload(payload);
44 │     return NextResponse.json({
45 │       ok: true,
46 │       url,
