 1 │ export type ColorScheme = "light" | "dark";
 2 │ /** What the Visitor has asked for — including "ask my OS". */
 3 │ export type ThemePreference = ColorScheme | "system";
 4 │ 
 5 │ /**
 6 │  * The site follows the operating system until the Visitor says otherwise. A
 7 │  * manual choice always wins and is persisted. Runtime applies this via
 8 │  * `next-themes`; this module is the contract.
 9 │  */
10 │ export const DEFAULT_THEME: ThemePreference = "system";
11 │ 
12 │ /** Used only where the OS expresses no preference at all. */
13 │ export const FALLBACK_SCHEME: ColorScheme = "dark";
14 │ 
15 │ export function resolveTheme(
16 │   preference: ThemePreference | null,
17 │   systemScheme: ColorScheme | null = null,
18 │ ): ColorScheme {
19 │   if (preference === "light" || preference === "dark") return preference;
20 │   return systemScheme ?? FALLBACK_SCHEME;
21 │ }
22 │ 
23 │ export function nextTheme(current: ColorScheme): ColorScheme {
24 │   return current === "dark" ? "light" : "dark";
