python3 - <<'PYEOF'
import io

def patch(path, old, new):
    s = io.open(path, encoding="utf-8").read()
    assert s.count(old) == 1, (path, s.count(old), old[:70])
    io.open(path, "w", encoding="utf-8").write(s.replace(old, new))
    print("patched", path)

patch("lib/theme.ts",
"""/** Used only where the OS expresses no preference at all. */
export const FALLBACK_SCHEME: ColorScheme = "dark";""",
"""/** Used only where the OS expresses no preference at all. */
export const FALLBACK_SCHEME: ColorScheme = "dark";

/**
 * The page background each scheme paints, as a literal hex.
 *
 * Three things outside CSS need this number and none of them can read a custom
 * property: the `themeColor` metadata pair, the unconditioned `theme-color`
 * tag the toggle keeps in sync, and the install manifest. They were three
 * copies of the same two values and the manifest's copy had drifted to white
 * in both slots. One declaration, so they cannot disagree again.
 *
 * These must track `--background` in `app/globals.css`.
 */
export const SCHEME_BACKGROUND = {
  light: "#ffffff",
  dark: "#09090b",
} as const satisfies Record<ColorScheme, string>;""")

patch("app/layout.tsx",
"""  themeColor: [
    { media: "(prefers-color-scheme: dark)", color: "#09090b" },
    { media: "(prefers-color-scheme: light)", color: "#ffffff" },
  ],""",
"""  themeColor: [
    { media: "(prefers-color-scheme: dark)", color: SCHEME_BACKGROUND.dark },
    { media: "(prefers-color-scheme: light)", color: SCHEME_BACKGROUND.light },
  ],""")

patch("components/theme-color.tsx",
"""import { useTheme } from "next-themes";

/** The two values the metadata export already declares, keyed by scheme. */
const THEME_COLOR = { light: "#ffffff", dark: "#09090b" } as const;""",
"""import { useTheme } from "next-themes";
import { SCHEME_BACKGROUND } from "@/lib/theme";""")

patch("components/theme-color.tsx",
"""    meta.content = THEME_COLOR[resolvedTheme === "light" ? "light" : "dark"];""",
"""    meta.content =
      SCHEME_BACKGROUND[resolvedTheme === "light" ? "light" : "dark"];""")

patch("app/manifest.ts",
"""import type { MetadataRoute } from "next";
import { site } from "@/lib/site";""",
"""import type { MetadataRoute } from "next";
import { site } from "@/lib/site";
import { FALLBACK_SCHEME, SCHEME_BACKGROUND } from "@/lib/theme";""")

patch("app/manifest.ts",
"""    background_color: "#ffffff",
    theme_color: "#ffffff",""",
"""    // A manifest holds one colour, not a pair — it is read before any page
    // runs, so there is nothing to ask. It gets the scheme the site falls back
    // to, which is dark; white here made an installed dark-first site open on
    // a white splash.
    background_color: SCHEME_BACKGROUND[FALLBACK_SCHEME],
    theme_color: SCHEME_BACKGROUND[FALLBACK_SCHEME],""")
PYEOF
grep -n "^import\|SCHEME_BACKGROUND" app/layout.tsx | head -20

