 4 │ 
 5 │ /**
 6 │  * One Post, as a row across the page.
 7 │  *
 8 │  * The reference draws Posts as cards in two columns, and it is right to: every
 9 │  * one of its Posts ships a 1200×630 cover, and a grid of pictures is what a
10 │  * grid is for. Ours ship none, and a card with no picture is a row that has
11 │  * been put in a box — half the width, so the summary breaks after four words,
12 │  * and at one Post it is a card beside a hole.
13 │  *
14 │  * So the picture is optional and the row is not. When a cover exists it leads
15 │  * the row as a 16:9 plate; when it does not, the row is a title, a sentence and
16 │  * two facts, which is the same shape a Project row has. That is the site's
17 │  * idiom — things on rules, full width — and it reads the same at one Post as at
18 │  * fifty.
19 │  */
20 │ export function PostItem({
21 │   post,
22 │   headingAs = "h2",
23 │ }: {
24 │   post: PostSummary;
25 │   headingAs?: "h2" | "h3";
26 │ }) {
27 │   const Heading = headingAs;
28 │ 
29 │   return (
30 │     <li className="border-b border-line last:border-b-0">
31 │       {/* `relative` scopes the stretched link to this row, so the next Post's
32 │           title never falls under this one's target. */}
33 │       <div className="group/post relative flex items-start gap-4 p-4 transition-[background-color] duration-150 ease-out hover:bg-accent-muted">
34 │         {post.image ? (
35 │           <div className="relative w-28 shrink-0 select-none max-sm:hidden">
36 │             {/* Grey until the pointer is on it: colour is the reward for
37 │                 choosing this one, not a thing six rows shout at once. */}
38 │             <Image
39 │               className="aspect-1200/630 rounded-lg grayscale transition-[filter] duration-300 ease-out group-hover/post:grayscale-0"
40 │               src={post.image}
41 │               alt=""
42 │               width={1200}
43 │               height={630}
44 │               quality={100}
45 │               unoptimized
46 │             />
47 │             <div className="pointer-events-none absolute inset-0 rounded-lg inset-ring-1 inset-ring-black/15 dark:inset-ring-white/15" />
48 │           </div>
49 │         ) : null}
50 │ 
51 │         <div className="flex min-w-0 flex-1 flex-col gap-1">
52 │           <Heading className="leading-snug font-medium text-balance">
53 │             <Link href={`/blog/${post.slug}`}>
