55 │               {post.title}
56 │             </Link>
57 │           </Heading>
58 │ 
59 │           <p className="typeset typeset-description text-muted-foreground">
60 │             {post.summary}
61 │           </p>
62 │ 
63 │           {/* Date and length, in the same mono the rest of the site measures
64 │               things in. A `dl` because they are facts about the Post, not two
65 │               more pieces of its prose. */}
66 │           <dl className="mt-1 flex items-center gap-2 font-mono text-xs text-muted-foreground/80 tabular-nums">
67 │             <dt className="sr-only">Published on</dt>
68 │             <dd>
