70 │                 {formatPostDate(post.publishedAt)}
71 │               </time>
72 │             </dd>
73 │             <span aria-hidden>·</span>
74 │             <dt className="sr-only">Reading time</dt>
75 │             <dd>{post.readingTimeMinutes} min read</dd>
76 │           </dl>
77 │         </div>
78 │       </div>
79 │     </li>
80 │   );
81 │ }
