export type SocialLink = {
  label: "X" | "GitHub" | "LinkedIn" | "Email";
  href: string;
};

export const site = {
  name: "Dhruv Sharma",
  handle: "Dhruv2mars",
  /** The role, shown under the name. Lowercase on purpose. */
  tagline: "agentic engineer",
  /**
   * The role line said more than one way. The first is the canonical one — it
   * is what `tagline` carries into metadata and structured data, where nothing
   * can rotate — and the rest widen it without the hero growing a paragraph.
   */
  flipSentences: [
    "agentic engineer",
    "prototyper",
    "tooling for coding agents",
  ] as const,
  /**
   * How the name sounds. `audio` is the answer — a recording of the name being
   * said — and `phonetic` is the same answer written down, shown on the button
   * for anyone who would rather read it. With no recording the button is not
   * drawn: a synthesised English voice has neither the breathy d nor the
   * retroflex v, so it says a different name confidently, which is worse than
   * silence.
   */
  pronunciation: {
    phonetic: "/dʱruːʋ ˈʃərmə/",
    audio: "/audio/dhruv-sharma.mp3" as string | null,
  },
  /**
   * The one-line description search results, feed readers and the install
   * manifest read. It is not rendered on the page: the hero already says the
   * name and the role, and a third line under them was prose the page did not
   * need. See `app/layout.tsx`.
   */
  description:
    "I build tooling for coding agents — repro harnesses, queues, local-first inference — and ship with them every day.",
  url: "https://dhruv2mars.com",
  /**
   * The portrait — currently the Codex pet, at source resolution. `null` here
   * is legal: the profile header draws a monogram at the same size, so the
   * slot cannot shift the layout either way, and this field is the whole
   * interface to it.
   */
  avatar: "/avatar/sunny.png" as string | null,
  socials: [
    { label: "X", href: "https://x.com/Dhruv2mars" },
    { label: "GitHub", href: "https://github.com/Dhruv2mars" },
    { label: "LinkedIn", href: "https://linkedin.com/in/dhruv2mars" },
    { label: "Email", href: "mailto:Dhruv2mars@gmail.com" },
  ] as const satisfies readonly SocialLink[],
  rssPath: "/feed.xml",
} as const;

/** Socials minus mailto, for `sameAs` in structured data. */
export function profileUrls(): string[] {
  return site.socials
    .filter((s) => !s.href.startsWith("mailto:"))
    .map((s) => s.href);
}

import { Rss, SOCIAL_ICONS } from "@/components/icons";
import { SiteWordmark } from "@/components/site-wordmark";
import { site } from "@/lib/site";

/**
 * The profiles, minus the mailbox.
 *
 * The overview's "say hi" row is the directory — it is the place that answers
 * "how do I reach this person", so it carries every way, email included. The
 * footer is a signature, and a signature does not repeat the directory: it
 * carries the three places the work lives, and the feed, which is a property
 * of the site rather than of the person and so belongs here and nowhere else.
 */
const FOOTER_SOCIALS = site.socials.filter(
  (social) => !social.href.startsWith("mailto:"),
);

export function SiteFooter() {
  return (
    <footer className="max-w-screen overflow-x-clip px-2">
      <div className="mx-auto border-x border-line md:max-w-3xl">
        <div className="screen-line-top screen-line-bottom">
          <div className="stripe-divider h-12" />
        </div>

        {/* One closing line: the copyright reads left, the glyphs read right,
            and on a phone they stack centred rather than squeezing. */}
        <div className="screen-line-top screen-line-bottom flex flex-col items-center justify-center gap-x-4 gap-y-3 px-4 py-3 text-sm text-muted-foreground sm:flex-row sm:justify-between">
          {/* The mark, not the legal name: the wordmark below signs the page
              and this line should agree with it. */}
          <span>
            &copy; {new Date().getFullYear()} {site.handle.toLowerCase()}.
          </span>

          {/* Four glyphs on one gutter. Icons stay 16px; links get a 32px box
              so touch does not depend on landing on the ink itself. */}
          <nav aria-label="Elsewhere" className="flex items-center gap-2 sm:gap-3">
            {FOOTER_SOCIALS.map((social) => {
              const Glyph = SOCIAL_ICONS[social.label];
              return (
                <a
                  key={social.label}
                  href={social.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={social.label}
                  title={social.label}
                  className="flex size-8 items-center justify-center transition-colors hover:text-foreground"
                >
                  <Glyph className="size-4" />
                </a>
              );
            })}
            {/* Same treatment as the socials beside it, and the same the
                command palette gives this entry (`external: true` in
                `lib/palette.ts`): a raw XML document replacing the page is a
                dead end with no way back. */}
            <a
              href={site.rssPath}
              target="_blank"
              rel="noopener noreferrer"
              aria-label="RSS feed"
              title="RSS feed — paste this address into a feed reader"
              className="flex size-8 items-center justify-center transition-colors hover:text-foreground"
            >
              <Rss className="size-4" />
            </a>
          </nav>
        </div>

      </div>

      <SiteWordmark
        text={site.handle.toLowerCase()}
        mobileText="d2m"
        className="text-foreground"
      />

      <div aria-hidden className="h-(--fade-bottom-height)" />

      <div className="pb-[env(safe-area-inset-bottom,0)]" />
    </footer>
  );
}

import Image from "next/image";
import { FlipSentences } from "@/components/flip-sentences";
import {
  HandwrittenArrow,
  HandwrittenNote,
} from "@/components/handwritten-note";
import { HeroChart } from "@/components/hero-chart";
import { PronounceName } from "@/components/pronounce-name";
import { formatFigureDate } from "@/lib/figure";
import { formatCompactTokens, formatTokenCount } from "@/lib/ai-activity";
import { getAiActivityPayload } from "@/lib/ai-activity-store";
import { buildHeroSeries, type HeroSeries } from "@/lib/hero-series";
import { site } from "@/lib/site";

/** "Dhruv Sharma" → "DS" for the missing-asset fallback. */
function initials(name: string): string {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

/** 128px on phones, 160px on desktop. */
function Avatar() {
  return (
    <div className="relative m-0.5 size-32 overflow-hidden rounded-full border border-line bg-muted ring-1 ring-border/50 select-none sm:size-40">
      {site.avatar ? (
        <span className="absolute top-[91.25%] left-[53.75%] aspect-[181/362] w-[90%] -translate-x-1/2 -translate-y-1/2">
          <Image
            src={site.avatar}
            alt={`${site.name}, profile portrait`}
            fill
            sizes="(min-width: 640px) 144px, 115px"
            priority
            className="object-contain"
          />
        </span>
      ) : (
        <span
          role="img"
          aria-label={`${site.name}, monogram`}
          className="absolute inset-0 grid place-items-center"
        >
          {/* A mount inset from the plate edge, like the figures elsewhere
              carry — the monogram is a mark this site drew, not a photograph
              that failed to load, and it should look like it was meant. */}
          <span
            aria-hidden
            className="absolute inset-2 rounded-md border border-line"
          />
          <span
            aria-hidden
            className="relative font-heading text-5xl font-medium tracking-tight text-foreground sm:text-6xl"
          >
            {initials(site.name)}
          </span>
        </span>
      )}
    </div>
  );
}

/**
 * What the figure says, for anyone not looking at it.
 *
 * The drawing is a shape; this is the same reading in words, and it carries
 * the smoothing window because a smoothed curve that does not say so is a
 * claim about days that were never worked that way.
 */
function heroDescription(series: HeroSeries): string {
  return [
    `${site.name}'s AI token use in ${series.year}, January 1 to`,
    `${formatFigureDate(series.to)}:`,
    `${formatTokenCount(series.total)} tokens,`,
    `busiest day ${formatFigureDate(series.peak.date)}`,
    `at ${formatCompactTokens(series.peak.tokens)}.`,
    `Drawn as a ${series.smoothingDays}-day mean.`,
  ].join(" ");
}

/**
 * The hero is a four-cell frame rather than a stacked block: the record
 * occupies a plate captioned like a figure, the avatar sits in its own gutter
 * column, and the name and role stack against the bottom edge so all three
 * meet on one baseline. Nothing here is centred.
 */
export async function ProfileHeader() {
  const { payload } = await getAiActivityPayload();
  const series = buildHeroSeries(payload);

  return (
    <div className="screen-line-bottom relative grid grid-cols-[auto_1fr] grid-rows-[1fr_auto] overflow-y-clip border-x border-line">
      {/* The plate carries no axis title — the numbers up its left edge are
          bare, which is right inside the frame and leaves the drawing unnamed.
          The note says what is being counted, from the gutter, in the same
          hand the "say hi" note is written in, and only where there is a
          gutter to hold it. */}
      <HandwrittenNote className="top-32 left-full ml-4 hidden w-28 flex-col items-start text-left pointer-fine:xl:flex">
        <span className="translate-x-[14px] rotate-6">token usage</span>
        <HandwrittenArrow className="mt-0.5 -translate-x-2 -translate-y-[9px] rotate-[136deg]" />
      </HandwrittenNote>

      {/* Nothing bleeds out of here. The reference lets its hero texture run
          past the rail and off the screen; ours does not. A pattern outside
          the frame turns the top of the page into wallpaper, and the only
          lines the hero needs are the ones that divide it.

          The plate spans the whole rail rather than the column beside the
          avatar, so the year opens at the frame's own left edge — which puts
          the opening weeks, and the two month labels over them, behind the
          monogram. That is the truth of the figure rather than a crop of it:
          those are the quietest weeks of the record, the habit started small,
          and the mark is what stands in front of it. The scale is readable
          from 25M up, which is above the monogram's crown. */}
      <figure className="relative col-span-2 col-start-1 row-start-1 aspect-[3/2] sm:aspect-[766/394]">
        <HeroChart
          points={series.points.map(({ day, value }) => ({ day, value }))}
          months={series.months}
          ticks={series.ticks}
          xDomain={series.xDomain}
          yDomain={series.yDomain}
          description={heroDescription(series)}
        />
        {/* Kept where every other figure on this site keeps it, and pared to
            the number alone — the year is legible off the month row and the
            smoothing window is carried by the figure's own description, so
            neither needs restating in the corner of the plate. */}
        <figcaption className="pointer-events-none absolute top-2 right-2 text-right text-[0.625rem]/none tracking-wide text-[color-mix(in_oklab,var(--muted-foreground)_60%,var(--background))] tabular-nums select-none sm:top-4 sm:right-4">
          Fig. 1.
        </figcaption>
      </figure>

      {/* Placed rather than flowed: the plate above now spans both columns, so
          the gutter has to be told it still owns column one — otherwise the
          grid opens a third column and the monogram lands on the wrong side
          of the page. */}
      <div className="flex flex-col sm:col-start-1 sm:row-span-2 sm:row-start-1">
        {/* No rule across the plate — the panels below draw their hairlines to
            200vw so the page reads as one ruled sheet, and one run through here
            would cut the figure in half at the height of the monogram's crown.
            A picture is not ruled. But the square still has to read as a square:
            two edges and it is a corner the curve runs out of, so the top is
            drawn to the box's own width and stops there. Top and right, the two
            sides that face the drawing; the frame supplies the other two.

            Opaque, and positioned so it is. The plate runs the full rail and
            the box stands on its bottom-left, so an unfilled square shows the
            curve through the four corners the circle does not reach — the mark
            then reads as a cutout laid over the drawing instead of a plate the
            drawing runs behind. The fill needs `relative` to land: unpositioned,
            it would paint under the figure and show nothing. */}
        <div className="relative mt-auto shrink-0 border-t border-r border-line bg-background">
          <Avatar />
        </div>
      </div>

      <div className="flex flex-col sm:col-start-2 sm:row-start-2">
        <div className="z-1 mt-auto border-t border-line">
          <h1 className="-translate-y-px flex items-center gap-2 pl-4 text-[2rem]/none font-medium tracking-tight">
            {site.name}
            {/* Inside the heading, not beside it: the button is about this
                name, and a name and the way to hear it are one object. */}
            <PronounceName />
          </h1>
          {/* The one line that reads as a caption rather than as prose, so it
              is set in mono at the small size — and swept once on arrival,
              which is the reference's own way of pointing at it without
              shouting. */}
          <FlipSentences
            sentences={site.flipSentences}
            className="h-12.5 border-t border-line py-1 pl-4 font-mono text-sm text-balance text-muted-foreground sm:h-9"
          />
        </div>
      </div>
    </div>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { ArrowLeft } from "@/components/icons";
import { glossaryComponents } from "@/components/glossary";
import { CustomMDX } from "@/components/mdx";
import {
  Panel,
  PanelContent,
  PanelDescription,
  PanelHeader,
  PanelTitle,
} from "@/components/panel";
import { PostActions } from "@/components/post-actions";
import { PostNeighbours } from "@/components/post-neighbours";
import { getPostBySlug, getPublishedPosts } from "@/lib/blog";
import { splitGlossary } from "@/lib/glossary";
import { findNeighbours, formatPostDate, postMarkdown } from "@/lib/posts";
import { ogImagePath } from "@/lib/discovery";
import { serializeJsonLd } from "@/lib/json-ld";
import { site } from "@/lib/site";

type PageProps = { params: Promise<{ slug: string }> };

export function generateStaticParams() {
  return getPublishedPosts().map((post) => ({ slug: post.slug }));
}

export async function generateMetadata({
  params,
}: PageProps): Promise<Metadata> {
  const { slug } = await params;
  const post = getPostBySlug(slug);
  if (!post) return {};

  const image = post.image ?? ogImagePath(post.title);
  const url = `${site.url}/blog/${post.slug}`;

  return {
    title: post.title,
    description: post.summary,
    alternates: { canonical: url },
    openGraph: {
      type: "article",
      title: post.title,
      description: post.summary,
      url,
      publishedTime: post.publishedAt,
      images: [{ url: image }],
    },
    twitter: {
      card: "summary_large_image",
      title: post.title,
      description: post.summary,
      images: [image],
    },
  };
}

export default async function PostPage({ params }: PageProps) {
  const { slug } = await params;
  const post = getPostBySlug(slug);
  if (!post) notFound();

  const url = `${site.url}/blog/${post.slug}`;

  // The definitions come out of the body and go back beside the terms they
  // define. `postMarkdown` is handed the source, not this, so what a model
  // gets is still the whole post.
  const { body, terms } = splitGlossary(post.content);

  // The index is newest-first, so the neighbours come from the same order the
  // Visitor saw on the way in.
  const { newer, older } = findNeighbours(getPublishedPosts(), post.slug);
  const neighbour = (post: { slug: string; title: string } | null) =>
    post ? { slug: post.slug, title: post.title } : null;

  const jsonLd = [
    {
      "@context": "https://schema.org",
      "@type": "BlogPosting",
      headline: post.title,
      description: post.summary,
      datePublished: post.publishedAt,
      dateModified: post.updatedAt ?? post.publishedAt,
      url,
      image: `${site.url}${post.image ?? ogImagePath(post.title)}`,
      author: { "@type": "Person", name: site.name, url: site.url },
      ...(post.tags?.length ? { keywords: post.tags } : {}),
      isPartOf: { "@type": "Blog", "@id": `${site.url}/blog` },
    },
    {
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      itemListElement: [
        { "@type": "ListItem", position: 1, name: "Home", item: site.url },
        {
          "@type": "ListItem",
          position: 2,
          name: "Blog",
          item: `${site.url}/blog`,
        },
        { "@type": "ListItem", position: 3, name: post.title, item: url },
      ],
    },
  ];

  return (
    <article className="[--separator-height:--spacing(8)]">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
      />

      {/* The toolbar: the way back on the left, what you can do with the post
          on the right. Above the title because it is about the document rather
          than in it — a share button under a thousand words is a share button
          you decided to press in the first paragraph and then had to hunt
          for. */}
      <div className="screen-line-bottom flex items-center justify-between gap-2 border-x border-line py-2 pr-2 pl-4">
        <Link
          href="/blog"
          className="link-underline extend-touch-target inline-flex items-center gap-1.5 text-sm text-muted-foreground transition-colors hover:text-foreground"
        >
          <ArrowLeft className="size-3.5" />
          Blog
        </Link>

        <PostActions
          markdown={postMarkdown(post, url, post.content)}
          rawUrl={`${url}/raw.md`}
          url={url}
          title={post.title}
          newer={neighbour(newer)}
          older={neighbour(older)}
        />
      </div>

      <Panel>
        {/* The one title on the site closed by a hairline on both sides, so
            it is the one that has to be given a band to sit in rather than
            being set flush against the rule above it. */}
        <PanelHeader>
          <PanelTitle as="h1" className="py-6">
            {post.title}
          </PanelTitle>
