/**
 * Title and summary — the two things a row actually draws.
 *
 * Not the body, and not the tags either: a filter that matched text the row
 * never shows returns a Post with nothing on it to say why it matched, which
 * reads as a bug even when it is a hit. Tags are not drawn anywhere, so they
 * are not matched here; they go out as `keywords` in the Post's structured
 * data, where a machine reads them and a Visitor is never puzzled by them.
 */
export function searchPosts<T extends Pick<PostSummary, "title" | "summary">>(
  posts: readonly T[],
  query: string,
): T[] {
  return filterByQuery(posts, query, (post) => [post.title, post.summary]);
}

