// Screenshot + DOM harness for site review.
// usage: bun shot.mjs <url> <outPrefix> [--w 1440] [--h 900] [--theme dark|light]
//                     [--full] [--click <selector>] [--press <key>] [--type <sel>=<text>]
//                     [--wait <ms>] [--scroll <px>]
import { chromium } from "playwright-core";

const argv = process.argv.slice(2);
const url = argv[0];
const out = argv[1];
const flag = (n, d) => { const i = argv.indexOf("--" + n); return i === -1 ? d : argv[i + 1]; };
const has = (n) => argv.includes("--" + n);

const width = Number(flag("w", 1440));
const height = Number(flag("h", 900));

const browser = await chromium.launch({ channel: "chrome", headless: true });
const ctx = await browser.newContext({
  viewport: { width, height },
  deviceScaleFactor: 2,
  colorScheme: flag("theme", "light"),
  reducedMotion: "no-preference",
});
const page = await ctx.newPage();

const consoleErrors = [];
page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text()); });
page.on("pageerror", (e) => consoleErrors.push("pageerror: " + e.message));

const resp = await page.goto(url, { waitUntil: "networkidle", timeout: 45000 });
await page.waitForTimeout(Number(flag("wait", 700)));

for (let i = 0; i < argv.length; i++) {
  if (argv[i] === "--click") { await page.click(argv[i + 1], { timeout: 8000 }).catch((e) => consoleErrors.push("click failed: " + e.message)); await page.waitForTimeout(500); }
  if (argv[i] === "--press") { await page.keyboard.press(argv[i + 1]); await page.waitForTimeout(500); }
  if (argv[i] === "--type") { const [s, ...t] = argv[i + 1].split("="); await page.fill(s, t.join("=")).catch((e) => consoleErrors.push("type failed: " + e.message)); await page.waitForTimeout(600); }
  if (argv[i] === "--scroll") { await page.mouse.wheel(0, Number(argv[i + 1])); await page.waitForTimeout(600); }
}

await page.screenshot({ path: out + ".png", fullPage: has("full") });

const facts = await page.evaluate(() => {
  const de = document.documentElement;
  const small = [];
  for (const el of document.querySelectorAll('a,button,[role="button"],[role="menuitem"],input,select,summary,[tabindex]:not([tabindex="-1"])')) {
    const r = el.getBoundingClientRect();
    if (r.width === 0 || r.height === 0) continue;
    if (r.width < 24 || r.height < 24) small.push({ tag: el.tagName.toLowerCase(), text: (el.textContent || el.getAttribute("aria-label") || "").trim().slice(0, 40), w: Math.round(r.width), h: Math.round(r.height) });
  }
  const headings = [...document.querySelectorAll("h1,h2,h3,h4")].map((h) => h.tagName + ": " + h.textContent.trim().slice(0, 80));
  const imgsNoAlt = [...document.querySelectorAll("img")].filter((i) => i.getAttribute("alt") === null).map((i) => i.getAttribute("src"));
  return {
    title: document.title,
    scrollWidth: de.scrollWidth,
    clientWidth: de.clientWidth,
    horizontalOverflow: de.scrollWidth > de.clientWidth + 1,
    headings,
    h1Count: document.querySelectorAll("h1").length,
    smallTargets: small.slice(0, 40),
    smallTargetCount: small.length,
    imgsMissingAlt: imgsNoAlt,
    text: document.body.innerText.replace(/\n{3,}/g, "\n\n").slice(0, 9000),
  };
});

console.log(JSON.stringify({ url, status: resp?.status(), viewport: { width, height }, theme: flag("theme", "light"), consoleErrors, ...facts }, null, 2));
await browser.close();
