export const meta = {
  name: 'site-critique',
  description: 'Parallel Codex (gpt-5.6-luna, xhigh) critiques of each part of the portfolio, then one whole-site critic',
  phases: [
    { title: 'Parts' },
    { title: 'Whole' },
  ],
}

const SHOTS = '/tmp/critique/shots'
const REPO = '/Users/dhruv2mars/dev/github/portfolio'
const OUT = '/tmp/critique/reports'

const FINDINGS = {
  type: 'object',
  required: ['surface', 'ran', 'findings'],
  properties: {
    surface: { type: 'string' },
    ran: { type: 'string', description: 'ok | codex-failed | partial — what actually happened' },
    verdict: { type: 'string', description: '2-3 sentence overall read of this part' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['severity', 'title', 'detail'],
        properties: {
          severity: { type: 'string', enum: ['high', 'medium', 'low', 'praise'] },
          title: { type: 'string', description: 'one line, <= 80 chars' },
          detail: { type: 'string', description: 'what is wrong, on which screenshot, and why it matters' },
          suggestion: { type: 'string' },
        },
      },
    },
  },
}

const PARTS = [
  {
    key: 'masthead',
    label: 'Masthead & hero figure',
    shots: ['home-1440-dark', 'home-1440-light', 'home-2560', 'home-1024', 'home-1280'],
    brief: `The masthead: the Fig. 1 token-usage plate, the circular portrait, the name with its pronounce button, and the rotating role line. Judge it as a hiring manager who has sixty seconds. Is the figure legible as a figure? Does the portrait crop read as deliberate? Do the four cells sit on one baseline? Does the plate's y-axis scale (25M..150M) read cleanly at every width, and does the curve stand up in its plate rather than hugging the floor? Check 2560 and 1024 for the frame breaking or the figure stretching. Check light vs dark for the curve losing contrast against its plate.`,
  },
  {
    key: 'home-ia',
    label: 'Home scroll & information architecture',
    shots: ['home-1440-full', 'home-768-full'],
    brief: `The whole Home scroll top to bottom: Masthead, Overview, Projects (8), Blog (1), footer wordmark. Judge density, rhythm, and whether a skimming visitor gets the proof in sixty seconds. Is any panel dead weight? Is the hairline/rule system consistent, or does some panel draw a rule the others do not? Does the "Projects 8" / "Blog 1" superscript count read as intended? Does the footer wordmark (the blocky lowercase "dhruv2mars") sit correctly and read as a signature rather than as a broken graphic? Is the vertical rhythm even, or are there gaps that read as mistakes? At 768 does anything reflow badly?`,
  },
  {
    key: 'mobile',
    label: 'Phone (390) across every surface',
    shots: ['home-390-full', 'home-390-light', 'projects-390', 'blog-390', 'post-390-full', 'notfound-390'],
    brief: `Every surface at 390x844, which is the width most visitors actually use. Look hard for: horizontal overflow, text that wraps to a single orphan word, touch targets that look smaller than a thumb, the hero figure becoming unreadable, the footer wordmark clipping or overflowing, the mobile dock covering content, and light-vs-dark parity on Home. Say plainly whether this site is good on a phone or merely survivable.`,
  },
  {
    key: 'projects',
    label: 'Projects index, filter, and row disclosure',
    shots: ['projects-1440', 'projects-row-open', 'projects-query', 'projects-typed', 'projects-nohit'],
    brief: `The /projects surface. A row is a name and two doors; clicking the row discloses a description, a language, a status ("published on npm") and a year. projects-row-open shows one row expanded. projects-query is the URL ?q=queue landing pre-filtered; projects-typed is the same filter typed into the field; projects-nohit is a query with no matches. Judge: is it obvious a row opens? Does the expanded state look designed or does it look like a layout shift? Does the count in the header update honestly? Is the empty state good or is it a shrug? Is the filter field findable?`,
  },
  {
    key: 'blog',
    label: 'Blog index and the Post reading experience',
    shots: ['blog-1440', 'blog-typed', 'blog-nohit', 'post-1440-full', 'post-1440-light', 'post-menu-open'],
    brief: `The /blog index and the single Post. A blog row is now a title, a date and a reading time — the summary line was deliberately removed. The Post page carries a toolbar (back, copy as Markdown, hand to a model, share), glossary marks beside defined terms at first use, and neighbour links at the end. post-menu-open shows the toolbar menu open. Judge: does a one-post index look thin or deliberate? Is the removed summary a loss? Is the Post's typography good for reading 5 minutes of prose — measure, leading, code blocks, headings? Do the glossary marks help or interrupt? Is light mode as good as dark for long reading?`,
  },
  {
    key: 'chrome',
    label: 'Header, nav, command palette, theme',
    shots: ['palette-open', 'home-1440-dark', 'home-1440-light', 'post-menu-open', 'mobile-dock'],
    brief: `The site chrome: the sticky header with the "dhruv2mars" mark, the Projects/Blog nav, the ⌘K affordance, and the command palette itself (palette-open shows it open, listing Go / Home / Projects / Blog / Posts). Judge: is the ⌘K badge discoverable without being noisy? Is the palette well-organised or is it a list of everything? Does the header mark compete with the page's own h1? Is the theme switch findable? Compare the dark and light Home screenshots as a pair — is one clearly the designed one and the other an afterthought?`,
  },
  {
    key: 'edges',
    label: '404, empty states, and accessibility surface',
    shots: ['notfound-1440', 'notfound-390', 'blog-nohit', 'projects-nohit', 'post-1440-light'],
    brief: `The pages nobody designs: the 404 (which draws "404" as a field of measured cells), and the two no-results states. Judge whether these feel like the same site or like fallbacks. Then, using the DOM facts JSON attached (smallTargets lists every interactive element under 24x24 with its measured size), say which of those are real accessibility problems on a touch device and which are false positives because a larger hit area is layered over them. Be concrete: name the element and its size.`,
  },
]

function shotArgs(shots) {
  return shots.map((s) => `-i ${SHOTS}/${s}.png`).join(' ')
}

function factsCat(shots) {
  return shots.map((s) => `${SHOTS}/${s}.json`).join(' ')
}

phase('Parts')

const results = await parallel(
  PARTS.map((part) => () =>
    agent(
      `You are coordinating one slice of a design critique. You do NOT critique yourself — Codex does. Your job is to run Codex correctly and return its findings as structured data.

Working directory: ${REPO}. Do not edit any file in the repo. Screenshots live in ${SHOTS}.

STEP 1. Write the critique prompt to a file:

  mkdir -p ${OUT}
  cat > ${OUT}/${part.key}-prompt.md <<'PROMPT'
You are reviewing a personal portfolio site (dhruv2mars.com) built as a proof surface for engineers and hiring managers. It is deliberately built in the design idiom of chanhdai.com: hairline rules, panels, mono numerals, figures with captions, nothing centred. The design contract is in DESIGN.md and the vocabulary in CONTEXT.md in this repo — READ BOTH FIRST, because a deviation from the contract is a finding and a faithful execution of it is not.

Your slice: ${part.label}.

${part.brief}

The attached PNG screenshots are of the real production build, captured at deviceScaleFactor 2. Their names, in the order attached: ${part.shots.join(', ')}.

Machine-measured DOM facts for the same pages are in these JSON files — read them with cat, they contain title, scrollWidth vs clientWidth (horizontal overflow), the full heading outline, every interactive element under 24x24 with its measured size, images missing alt, console errors, failed requests, and the page's full innerText:
${factsCat(part.shots)}

(Note: the two 404s on /_vercel/insights and /_vercel/speed-insights are expected — those scripts only exist when deployed to Vercel. Not a finding.)

Be a harsh, specific critic. Rules:
- Every finding names the screenshot it is visible in and says what is wrong in concrete visual terms.
- No generic design advice. "Improve visual hierarchy" is worthless. "The role line under the name sits 12px too far from the baseline of the name, so they read as two blocks rather than one" is a finding.
- If something is genuinely excellent, say so and say why — mark it praise. Do not manufacture praise.
- Do not invent problems to fill a quota. Three real findings beat ten padded ones.
- Rank by severity: high (a hiring manager notices and it costs credibility), medium (a designer notices), low (a nit).

Write your critique as markdown: a short verdict paragraph, then a numbered list of findings, each with a severity tag, what is wrong, why it matters, and a concrete fix.
PROMPT

STEP 2. Run Codex. Use exactly this, foreground, and give it the full 10 minutes:

  cd ${REPO} && codex exec -C ${REPO} --add-dir ${OUT} --add-dir ${SHOTS} --skip-git-repo-check -m gpt-5.6-luna -c model_reasoning_effort=xhigh --yolo ${shotArgs(part.shots)} -o ${OUT}/${part.key}-report.md "$(cat ${OUT}/${part.key}-prompt.md)"

Set the Bash timeout to 600000. If it times out or the report file is empty, retry ONCE with -c model_reasoning_effort=high instead of xhigh. If it fails twice, set ran="codex-failed" and return whatever partial output you have.

STEP 3. Read ${OUT}/${part.key}-report.md and return it as structured findings. Preserve Codex's specifics verbatim where you can — do not summarise a concrete measurement into a vague phrase. Set surface="${part.label}".`,
      { label: `critique:${part.key}`, phase: 'Parts', schema: FINDINGS, model: 'haiku', effort: 'high' },
    ),
  ),
)

const ok = results.filter(Boolean)
log(`${ok.length}/${PARTS.length} part critiques returned`)

phase('Whole')

const digest = ok
  .map((r) => `### ${r.surface} (${r.ran})\n${r.verdict || ''}\n` +
    (r.findings || []).map((f) => `- [${f.severity}] ${f.title} — ${f.detail}`).join('\n'))
  .join('\n\n')

const WHOLE = ['home-1440-full', 'home-390-full', 'projects-1440', 'blog-1440', 'post-1440-full', 'notfound-1440', 'palette-open', 'home-1440-light']

const final = await agent(
  `You are coordinating the FINAL whole-site critique. Codex does the critiquing; you run it and return the result.

Working directory: ${REPO}. Do not edit any repo file.

STEP 1. Write the prompt:

  cat > ${OUT}/whole-prompt.md <<'PROMPT'
You are the final critic of a personal portfolio site (dhruv2mars.com). Seven specialists have already reviewed individual parts. Your job is the thing none of them could do: judge the site AS A WHOLE.

Read DESIGN.md and CONTEXT.md in this repo first. The site is deliberately built in the idiom of chanhdai.com and is meant to convince an engineer or hiring manager, in under sixty seconds, that its author is exceptional. Its organising rule is that a section exists only when real, linkable proof fills it.

Attached screenshots, in order: ${WHOLE.join(', ')}. DOM facts: ${factsCat(WHOLE)}.

Here is what the seven specialists found. Treat it as evidence, not as truth — you may overrule any of it, and saying "this specialist is wrong, and here is why" is valuable:

${digest.slice(0, 14000)}

Answer these, in order, concretely:

1. THE SIXTY-SECOND TEST. A senior engineer lands on Home, scrolls once, and leaves. What do they now believe about this person? Be specific about what convinced them and what did not land.

2. THE WEAKEST LINK. Of everything on this site, what single thing most undermines its credibility? Name it and say what to do.

3. COHERENCE. Do all five surfaces read as one designed object, or does any of them read as built later by someone else? Point at the specific inconsistency.

4. THE PROOF PROBLEM. Eight projects, one blog post. Is the ratio a problem? Does the one post make the Blog section look alive or look abandoned? Is the token-usage figure real proof of the "agentic engineer" claim, or is it a vanity metric dressed as a figure?

5. AGAINST THE REFERENCE. This is built to be measured against chanhdai.com. Where does it fall short of that bar, and where — if anywhere — does it beat it?

6. THE THREE CHANGES. If the author could make only three changes before showing this to someone hiring, what are they, in order? Each must be concrete enough to start on today.

Be blunt. Do not soften. Do not close with an encouraging summary. If the site is good, say which parts and why; if a part is weak, say so plainly.
PROMPT

STEP 2. Run it, foreground, Bash timeout 600000:

  cd ${REPO} && codex exec -C ${REPO} --add-dir ${OUT} --add-dir ${SHOTS} --skip-git-repo-check -m gpt-5.6-luna -c model_reasoning_effort=xhigh --yolo ${shotArgs(WHOLE)} -o ${OUT}/whole-report.md "$(cat ${OUT}/whole-prompt.md)"

Retry once at high effort if it times out or the report is empty.

STEP 3. Return the FULL text of ${OUT}/whole-report.md verbatim as your final output. Do not summarise it, do not trim it, do not add commentary. The report is the deliverable.`,
  { label: 'critique:whole-site', phase: 'Whole', model: 'haiku', effort: 'high' },
)

return { parts: ok, whole: final }

