export type SocialLink = {
  label: "X" | "GitHub" | "LinkedIn" | "Email";
  href: string;
};

export const site = {
  name: "Dhruv Sharma",
  handle: "Dhruv2mars",
  /** The role, shown under the name. Lowercase on purpose. */
  tagline: "agentic engineer",
  /**
   * The role line said more than one way. The first is the canonical one — it
   * is what `tagline` carries into metadata and structured data, where nothing
   * can rotate — and the rest widen it without the hero growing a paragraph.
   */
  flipSentences: [
    "agentic engineer",
    "prototyper",
    "tooling for coding agents",
  ] as const,
  /**
   * How the name sounds. `audio` is the answer — a recording of the name being
   * said — and `phonetic` is the same answer written down, shown on the button
   * for anyone who would rather read it. With no recording the button is not
   * drawn: a synthesised English voice has neither the breathy d nor the
   * retroflex v, so it says a different name confidently, which is worse than
   * silence.
   */
  pronunciation: {
    phonetic: "/dʱruːʋ ˈʃərmə/",
    audio: "/audio/dhruv-sharma.mp3" as string | null,
  },
  /**
   * The one-line description search results, feed readers and the install
   * manifest read. It is not rendered on the page: the hero already says the
   * name and the role, and a third line under them was prose the page did not
   * need. See `app/layout.tsx`.
   */
  description:
    "I build tooling for coding agents — repro harnesses, queues, local-first inference — and ship with them every day.",
  url: "https://dhruv2mars.com",
  /**
   * The portrait — currently the Codex pet, at source resolution. `null` here
   * is legal: the profile header draws a monogram at the same size, so the
   * slot cannot shift the layout either way, and this field is the whole
   * interface to it.
   */
  avatar: "/avatar/sunny.png" as string | null,
  socials: [
    { label: "X", href: "https://x.com/Dhruv2mars" },
    { label: "GitHub", href: "https://github.com/Dhruv2mars" },
    { label: "LinkedIn", href: "https://linkedin.com/in/dhruv2mars" },
    { label: "Email", href: "mailto:Dhruv2mars@gmail.com" },
  ] as const satisfies readonly SocialLink[],
  rssPath: "/feed.xml",
} as const;

/** Socials minus mailto, for `sameAs` in structured data. */
export function profileUrls(): string[] {
  return site.socials
    .filter((s) => !s.href.startsWith("mailto:"))
    .map((s) => s.href);
}

import { filterByQuery } from "@/lib/search";

/**
 * What a Post *is*, and the things you can do with one without touching a
 * disk.
 *
 * `lib/blog.ts` reads Posts off the filesystem, so anything that imports it is
 * server-only. A search box is not: it needs the shape, the date formatter and
 * the matcher in the browser. Splitting the pure half out is what lets the row
 * and the filter be shared by both sides instead of duplicated on one.
 */

export type PostFrontmatter = {
  title: string;
  publishedAt: string;
  /**
   * When the Post was last materially changed, if it ever was. Absent means
   * it still says what it said on the day it went up — which is the honest
   * default, and why `dateModified` falls back to `publishedAt` rather than
   * to the file's mtime, a number that moves when a typo is fixed.
   */
  updatedAt?: string;
  summary: string;
  /** Subject terms. Not drawn and not searched — see `searchPosts`. */
  tags?: string[];
  draft?: boolean;
  image?: string;
};

export type PostRecord = PostFrontmatter & {
  slug: string;
  content: string;
  readingTimeMinutes: number;
};

/**
 * A Post minus its body: everything a row draws and a search reads, and
 * nothing a list of fifty has to ship down the wire.
 */
export type PostSummary = Omit<PostRecord, "content">;

export function formatPostDate(date: string): string {
  const value = date.includes("T") ? date : `${date}T00:00:00`;
  return new Date(value).toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  });
}

/**
 * The title — the only prose a row draws.
 *
 * A filter that matched text the row never shows returns a Post with nothing
 * on it to say why it matched, which reads as a bug even when it is a hit.
 * That rules out the body, the tags, and — since the row stopped drawing it —
 * the summary. Both still leave the building: the summary as the Post's
 * description in metadata, feeds and social cards, the tags as `keywords` in
 * its structured data, where a machine reads them and a Visitor is never
 * puzzled by them.
 */
export function searchPosts<T extends Pick<PostSummary, "title">>(
  posts: readonly T[],
  query: string,
): T[] {
  return filterByQuery(posts, query, (post) => [post.title]);
}

export function findNeighbours<T extends { slug: string }>(
  posts: readonly T[],
  slug: string,
): { newer: T | null; older: T | null } {
  const index = posts.findIndex((post) => post.slug === slug);
  if (index === -1) return { newer: null, older: null };
  return {
    newer: posts[index - 1] ?? null,
    older: posts[index + 1] ?? null,
  };
}

/**
 * The post as plain markdown: what "Copy page" puts on the clipboard and what
 * `/blog/<slug>/raw.md` serves.
 *
 * The frontmatter is bookkeeping for the build, so it is not reproduced; the
 * two facts it holds that a reader wants — what this is and when it was
 * written — are restated as text instead. The canonical URL rides along
 * because the likeliest next thing to happen to this string is being pasted
 * into a model, and a model that cannot cite where the words came from will
 * invent somewhere.
 */
export function postMarkdown(
  post: Pick<PostSummary, "title" | "summary" | "publishedAt">,
  url: string,
  content: string,
): string {
  return (
    [
      `# ${post.title}`,
      `> ${post.summary}`,
      `${formatPostDate(post.publishedAt)} · ${url}`,
      content.trim(),
    ].join("\n\n") + "\n"
  );
}

import { describe, expect, test } from "bun:test";
import {
  findNeighbours,
  formatPostDate,
  postMarkdown,
  searchPosts,
  type PostSummary,
} from "@/lib/posts";

const post = (over: Partial<PostSummary>): PostSummary => ({
  slug: "a-post",
  title: "A Post",
  summary: "A sentence about it.",
  publishedAt: "2026-01-01",
  readingTimeMinutes: 3,
  ...over,
});

const POSTS: PostSummary[] = [
  post({
    slug: "gpt-5-6-review",
    title: "GPT-5.6 Review",
    summary: "Notes on burning three and a half billion tokens.",
    tags: ["models"],
  }),
  post({
    slug: "repro-harness",
    title: "Building a repro harness",
    summary: "Coding agents need a way to fail the same way twice.",
    tags: ["tooling", "agents"],
  }),
];

describe("searchPosts", () => {
  test("an empty query is not a filter", () => {
    expect(searchPosts(POSTS, "")).toHaveLength(2);
    expect(searchPosts(POSTS, "   ")).toHaveLength(2);
  });

  test("returns a copy, so a caller cannot sort the source out from under it", () => {
    expect(searchPosts(POSTS, "")).not.toBe(POSTS);
  });

  test("matches the title regardless of case", () => {
    expect(searchPosts(POSTS, "gpt").map((p) => p.slug)).toEqual([
      "gpt-5-6-review",
    ]);
  });

  test("does not match the summary, which the row stopped drawing", () => {
    // The word is in the summary and nowhere a Visitor can see it, so a row
    // returned for it would show nothing of why it matched.
    expect(searchPosts(POSTS, "billion")).toEqual([]);
  });

  test("does not match a tag, because a row never draws one", () => {
    // A hit whose row shows nothing of why it matched reads as a bug. Tags
    // go out as structured-data keywords instead.
    expect(searchPosts(POSTS, "tooling")).toEqual([]);
  });

  test("ignores spaces on both sides, so a fast typist still lands", () => {
    expect(searchPosts(POSTS, "reproharness").map((p) => p.slug)).toEqual([
      "repro-harness",
    ]);
    expect(searchPosts(POSTS, "  repro harness ").map((p) => p.slug)).toEqual([
      "repro-harness",
    ]);
  });

  test("no match is an empty list, never the whole list", () => {
    expect(searchPosts(POSTS, "kubernetes")).toEqual([]);
  });
});

describe("formatPostDate", () => {
  test("a date-only string is not dragged across a timezone", () => {
    // `2026-01-01` parsed as UTC and printed in a western zone is 31 December.
    // The formatter reads it as local midnight so the day printed is the day
    // written.
    expect(formatPostDate("2026-01-01")).toBe("January 1, 2026");
  });
});

describe("findNeighbours", () => {
  test("the middle of the list has one on each side", () => {
    const list = [post({ slug: "a" }), post({ slug: "b" }), post({ slug: "c" })];
    const { newer, older } = findNeighbours(list, "b");
    expect(newer?.slug).toBe("a");
    expect(older?.slug).toBe("c");
  });

  test("the newest post has nothing above it", () => {
    const list = [post({ slug: "a" }), post({ slug: "b" })];
    expect(findNeighbours(list, "a")).toMatchObject({ newer: null });
  });

  test("the oldest post has nothing below it", () => {
    const list = [post({ slug: "a" }), post({ slug: "b" })];
    expect(findNeighbours(list, "b")).toMatchObject({ older: null });
  });

  test("the only post is an island", () => {
    expect(findNeighbours([post({ slug: "a" })], "a")).toEqual({
      newer: null,
      older: null,
    });
  });

  test("an unknown slug is neighbourless, not an exception", () => {
    expect(findNeighbours([post({ slug: "a" })], "nope")).toEqual({
      newer: null,
      older: null,
    });
  });
});

describe("postMarkdown", () => {
  const source = postMarkdown(
    post({ title: "A Post", summary: "About it.", publishedAt: "2026-01-01" }),
    "https://example.com/blog/a-post",
    "\n\nBody text.\n",
  );

  test("opens with the title as an h1", () => {
    expect(source.startsWith("# A Post\n")).toBe(true);
  });

  test("carries the summary, the date and the canonical URL", () => {
    expect(source).toContain("> About it.");
    expect(source).toContain("January 1, 2026");
    expect(source).toContain("https://example.com/blog/a-post");
  });

  test("no frontmatter leaks into it", () => {
    expect(source).not.toContain("---");
  });

  test("ends in exactly one newline, so a paste is not padded", () => {
    expect(source.endsWith("Body text.\n")).toBe(true);
  });
});

import { Rss, SOCIAL_ICONS } from "@/components/icons";
import { SiteWordmark } from "@/components/site-wordmark";
import { site } from "@/lib/site";

/**
 * The profiles, minus the mailbox.
 *
 * The overview's "say hi" row is the directory — it is the place that answers
 * "how do I reach this person", so it carries every way, email included. The
 * footer is a signature, and a signature does not repeat the directory: it
 * carries the three places the work lives, and the feed, which is a property
 * of the site rather than of the person and so belongs here and nowhere else.
 */
const FOOTER_SOCIALS = site.socials.filter(
  (social) => !social.href.startsWith("mailto:"),
);

export function SiteFooter() {
  return (
    <footer className="max-w-screen overflow-x-clip px-2">
      <div className="mx-auto border-x border-line md:max-w-3xl">
        <div className="screen-line-top screen-line-bottom">
          <div className="stripe-divider h-12" />
        </div>

        {/* One closing line: the copyright reads left, the glyphs read right,
            and on a phone they stack centred rather than squeezing. */}
        <div className="screen-line-top screen-line-bottom flex flex-col items-center justify-center gap-x-4 gap-y-3 px-4 py-3 text-sm text-muted-foreground sm:flex-row sm:justify-between">
          {/* The mark, not the legal name: the wordmark below signs the page
              and this line should agree with it. */}
          <span>
            &copy; {new Date().getFullYear()} {site.handle.toLowerCase()}.
          </span>

          {/* Four glyphs on one gutter. Icons stay 16px; links get a 32px box
              so touch does not depend on landing on the ink itself. */}
          <nav aria-label="Elsewhere" className="flex items-center gap-2 sm:gap-3">
            {FOOTER_SOCIALS.map((social) => {
              const Glyph = SOCIAL_ICONS[social.label];
              return (
                <a
                  key={social.label}
                  href={social.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={social.label}
                  title={social.label}
                  className="flex size-8 items-center justify-center transition-colors hover:text-foreground"
                >
                  <Glyph className="size-4" />
                </a>
              );
            })}
            {/* Same treatment as the socials beside it, and the same the
                command palette gives this entry (`external: true` in
                `lib/palette.ts`): a raw XML document replacing the page is a
                dead end with no way back. */}
            <a
              href={site.rssPath}
              target="_blank"
              rel="noopener noreferrer"
              aria-label="RSS feed"
              title="RSS feed — paste this address into a feed reader"
              className="flex size-8 items-center justify-center transition-colors hover:text-foreground"
            >
              <Rss className="size-4" />
            </a>
          </nav>
        </div>

      </div>

      <SiteWordmark
        text={site.handle.toLowerCase()}
        mobileText="d2m"
        className="text-foreground"
      />

      <div aria-hidden className="h-(--fade-bottom-height)" />

      <div className="pb-[env(safe-area-inset-bottom,0)]" />
    </footer>
  );
}

