 1 │ "use client";
 2 │ 
 3 │ import { CloseIcon, SearchIcon } from "@/components/icons";
 4 │ 
 5 │ /**
 6 │  * The filter above a list. One field, used by the blog index and the projects
 7 │  * index, so the two pages type the same way — the second search box a Visitor
 8 │  * meets should teach them nothing new.
 9 │  *
10 │  * It owns no state: the list it filters does, because the list is the thing
11 │  * that has to re-render. See `PostSearch` and `ProjectSearch`.
12 │  */
13 │ export function SearchField({
14 │   value,
15 │   onChange,
16 │   label,
17 │   placeholder,
18 │ }: {
19 │   value: string;
20 │   onChange: (value: string) => void;
21 │   label: string;
22 │   placeholder: string;
23 │ }) {
24 │   return (
25 │     <div className="screen-line-bottom p-2">
26 │       <div className="relative flex items-center">
27 │         <SearchIcon
28 │           aria-hidden
29 │           className="pointer-events-none absolute left-3 size-4 text-muted-foreground"
30 │         />
31 │         <input
32 │           type="search"
33 │           value={value}
34 │           onChange={(event) => onChange(event.target.value)}
35 │           onKeyDown={(event) => {
36 │             // Escape empties the field before it does anything else — the same
37 │             // key the palette closes with, doing the same job here.
38 │             if (event.key === "Escape" && value) {
39 │               event.preventDefault();
40 │               onChange("");
41 │             }
42 │           }}
43 │           placeholder={placeholder}
44 │           aria-label={label}
45 │           name="q"
46 │           autoComplete="off"
47 │           spellCheck={false}
48 │           /* 16px on a phone: anything smaller and iOS zooms the page on focus,
49 │              which lands the Visitor somewhere they did not ask to be. */
50 │           className="h-9 w-full rounded-lg border border-border bg-transparent pr-9 pl-9 text-base text-foreground placeholder:text-muted-foreground sm:text-sm dark:bg-input/30"
51 │         />
52 │         {value ? (
53 │           <button
54 │             type="button"
55 │             onClick={() => onChange("")}
56 │             aria-label="Clear search"
57 │             className="absolute right-1.5 flex size-6 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:text-foreground"
58 │           >
59 │             <CloseIcon className="size-4" />
60 │           </button>
61 │         ) : null}
62 │       </div>
63 │     </div>
64 │   );
65 │ }
66 │ 
67 │ /**
68 │  * What a filter did, for someone who cannot see the list change shape. The
69 │  * count is the whole message: a screen reader announcing every matching title
70 │  * on every keystroke is worse than silence.
71 │  */
72 │ export function SearchStatus({
73 │   count,
74 │   noun,
75 │ }: {
76 │   count: number;
77 │   noun: string;
78 │ }) {
79 │   return (
80 │     <p role="status" className="sr-only">
81 │       {count === 1 ? `1 ${noun}` : `${count} ${noun}s`}
82 │     </p>
83 │   );
84 │ }

