const b = await chromium.launch();

async function at(w, h) {
  const p = await b.newPage({ viewport: { width: w, height: h } });
  await p.goto("http://localhost:3000/blog", { waitUntil: "networkidle" });
  const gap = await p.evaluate(() => {
    const panel = document.querySelector('[data-slot="panel"]');
    const footer = document.querySelector("footer");
    return {
      panelBottom: panel?.getBoundingClientRect().bottom ?? null,
      footerTop: footer?.getBoundingClientRect().top ?? null,
      docH: document.documentElement.scrollHeight,
      vh: innerHeight,
    };
  });
  console.log(`blog ${w}x${h}`, JSON.stringify(gap), "gap:", (gap.footerTop - gap.panelBottom).toFixed(1));

  // palette
  await p.goto("http://localhost:3000/", { waitUntil: "networkidle" });
  await p.keyboard.press("Meta+k");
  await p.waitForTimeout(400);
  const pal = await p.evaluate(() => {
    const lb = document.querySelector('[role="listbox"]');
    if (!lb) return null;
    const rows = [...lb.querySelectorAll('[role="option"]')];
    const last = rows.at(-1)?.getBoundingClientRect();
    const r = lb.getBoundingClientRect();
    return {
      listH: r.height, scrollH: lb.scrollHeight, rows: rows.length,
      overflow: lb.scrollHeight - lb.clientHeight,
      // is the row at the visible bottom edge cut in half?
      partial: rows.filter((el) => {
        const t = el.getBoundingClientRect().top - r.top;
        const bmm = el.getBoundingClientRect().bottom - r.top;
        return t < r.height && bmm > r.height;
      }).length,
      escInLegend: !!document.body.innerText.match(/esc/i),
    };
  });
  console.log(`palette ${w}x${h}`, JSON.stringify(pal));
  await p.close();
}
await at(390, 844);
await at(1280, 800);
await at(1440, 900);

// post title wrapping
const p = await b.newPage({ viewport: { width: 390, height: 844 } });
await p.goto("http://localhost:3000/blog/gpt-5-6-review", { waitUntil: "networkidle" });
console.log("title", JSON.stringify(await p.locator("h1").first().evaluate((e) => ({ text: e.innerText, w: e.getBoundingClientRect().width, lines: Math.round(e.getBoundingClientRect().height / parseFloat(getComputedStyle(e).lineHeight)) }))));
// where does it break?
console.log("wrap", await p.locator("h1").first().evaluate((e) => {
  const r = document.createRange(); const out = [];
  const tn = document.createTreeWalker(e, NodeFilter.SHOW_TEXT).nextNode();
  let prevTop = null;
  for (let i = 0; i < tn.data.length; i++) { r.setStart(tn, i); r.setEnd(tn, i + 1);
    const t = Math.round(r.getBoundingClientRect().top);
    if (prevTop !== null && t !== prevTop) out.push(`⏎${tn.data[i]}`); else out.push(tn.data[i]);
    prevTop = t; }
  return out.join("");
}));
await b.close();
EOF
