cd /tmp/critique/harness && cat > sweep.mjs <<'EOF'
import { chromium } from "playwright-core";
const b = await chromium.launch();
const ROUTES = ["/", "/projects", "/blog", "/blog/gpt-5-6-review", "/nope"];
const W = [390, 768, 1024, 1280, 1440, 2560];
for (const w of W) {
  for (const r of ROUTES) {
    const p = await b.newPage({ viewport: { width: w, height: 900 } });
    const errs = [], reqs = [];
    p.on("console", (m) => m.type() === "error" && errs.push(m.text()));
    p.on("requestfailed", (q) => reqs.push(q.url()));
    await p.goto("http://localhost:3000" + r, { waitUntil: "networkidle" });
    const d = await p.evaluate(() => {
      const small = [...document.querySelectorAll("a,button,[role=option],input,summary")]
        .filter((e) => { const b = e.getBoundingClientRect(); return b.width > 0 && (b.width < 24 || b.height < 24); })
        .map((e) => `${e.tagName}:${(e.getAttribute("aria-label") || e.textContent || "").trim().slice(0, 28)}:${Math.round(e.getBoundingClientRect().width)}x${Math.round(e.getBoundingClientRect().height)}`);
      return {
        overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth,
        h1: document.querySelectorAll("h1").length,
        heads: [...document.querySelectorAll("h1,h2,h3,h4")].map((e) => e.tagName),
        small,
        noAlt: [...document.querySelectorAll("img")].filter((e) => !e.hasAttribute("alt")).length,
      };
    });
    const bad = d.overflow || d.h1 !== 1 || d.small.length || d.noAlt || errs.length || reqs.length;
    if (bad) console.log(w, r, JSON.stringify({ ...d, errs, reqs }));
    await p.close();
  }
}
console.log("sweep done");
await b.close();
EOF
PLAYWRIGHT_BROWSERS_PATH=/tmp/critique/browsers bun sweep.mjs 2>&1 | tail -40

