import { chromium } from "playwright-core";
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 3 });
const p = await ctx.newPage();
for (const r of ["/", "/projects", "/blog", "/blog/gpt-5-6-review", "/nope"]) {
  await p.goto("http://localhost:3000" + r, { waitUntil: "networkidle" });
  const d = await p.evaluate(() => {
    const coarse = matchMedia("(pointer: coarse)").matches;
    const bad = [];
    for (const e of document.querySelectorAll("a,button,input,summary")) {
      const own = e.getBoundingClientRect();
      if (own.width === 0) continue;
      // union of the element with its ::after / ::before extension and any
      // absolutely-positioned overlay child that is its real hit area
      let x1 = own.left, y1 = own.top, x2 = own.right, y2 = own.bottom;
      for (const pe of ["::before", "::after"]) {
        const s = getComputedStyle(e, pe);
        if (s.content === "none" || s.position !== "absolute") continue;
        const ins = (v) => (v === "auto" ? 0 : parseFloat(v) || 0);
        x1 -= -ins(s.left); y1 -= -ins(s.top); x2 -= ins(s.right); y2 -= ins(s.bottom);
        x1 = Math.min(x1, own.left + ins(s.left)); y1 = Math.min(y1, own.top + ins(s.top));
        x2 = Math.max(x2, own.right - ins(s.right)); y2 = Math.max(y2, own.bottom - ins(s.bottom));
      }
      for (const c of e.children) {
        const cs = getComputedStyle(c);
        if (cs.position !== "absolute") continue;
        const cb = c.getBoundingClientRect();
        if (cb.width > own.width || cb.height > own.height) {
          x1 = Math.min(x1, cb.left); y1 = Math.min(y1, cb.top);
          x2 = Math.max(x2, cb.right); y2 = Math.max(y2, cb.bottom);
        }
      }
      const w = x2 - x1, h = y2 - y1;
      if (w < 24 || h < 24) bad.push(`${e.tagName}:${(e.getAttribute("aria-label") || e.textContent || "").trim().slice(0, 24)}:${w.toFixed(0)}x${h.toFixed(0)}`);
    }
    return { coarse, bad };
  });
  console.log(r, JSON.stringify(d));
}
await b.close();
EOF
