        overflow: hidden;
      }
      canvas { display: block; width: 100%; }
      .stage.tight { padding: 0 16px; }
      aside {
        border-left: 1px solid var(--line);
        background: var(--panel);
        padding: 20px 18px 40px;
        display: flex;
        flex-direction: column;
