        max-height: 100vh;
        overflow-y: auto;
      }
      @media (max-width: 860px) { aside { border-left: 0; border-top: 1px solid var(--line); max-height: none; } }
      fieldset { border: 0; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 12px; }
      legend {
        font-size: 10px;
        letter-spacing: 0.12em;
        text-transform: uppercase;
